import React, { useState, useEffect, useMemo } from 'react';
import { useLocation } from 'react-router-dom';
import { cn } from '@/shared/lib/cn';
import { useTheme } from '@/hooks/useTheme';

// Tus imágenes renombradas a .jpg
const fallbackBackground = '/backgrounds/bg5.webp';
const backgrounds = [
  '/backgrounds/bg1.jpg',
  '/backgrounds/bg2.jpg',
  '/backgrounds/bg3.jpg',
  '/backgrounds/bg4.jpg',
  fallbackBackground,
];

interface RandomBackgroundProps {
  children?: React.ReactNode; // Hacemos children opcional
  className?: string;
}

export const RandomBackground: React.FC<RandomBackgroundProps> = ({ children, className }) => {
  const { pathname } = useLocation();
  const [bgUrl, setBgUrl] = useState(fallbackBackground);
  const [isLoaded, setIsLoaded] = useState(false);
  const { prefs } = useTheme();

  const resolvedBackground = useMemo(() => {
    if (prefs?.isCustom && prefs.background) {
      return prefs.background;
    }
    const randomBg = backgrounds[Math.floor(Math.random() * backgrounds.length)];
    return randomBg || fallbackBackground;
  }, [prefs.background, prefs.isCustom, pathname]);

  useEffect(() => {
    setIsLoaded(false);
    const img = new Image();
    img.src = resolvedBackground;
    img.onload = () => {
      setBgUrl(resolvedBackground);
      setIsLoaded(true);
    };
  }, [resolvedBackground]);

  // Si el usuario desactivó "Fondo Animado" o "Partículas" desde el engrane,
  // podemos mostrar un color sólido o el fondo estático sin efectos extra.
  // Aquí usamos las preferencias para decidir la opacidad o efectos.

  return (
    <div className={cn('fixed inset-0 -z-10 overflow-hidden bg-black', className)}>
      {/* Capa de imagen de fondo */}
      <div
        className={cn(
          'absolute inset-0 bg-cover bg-center bg-no-repeat transition-opacity duration-700',
          isLoaded ? 'opacity-100 scale-100' : 'opacity-0 scale-105'
        )}
        style={{ backgroundImage: `url(${bgUrl || fallbackBackground})` }}
      />

      {/* Overlay Neón (Controlado por el engrane: glowLevel) */}
      <div 
        className={cn(
          'absolute inset-0 bg-gradient-to-br from-cyan-900/30 via-purple-900/30 to-pink-900/30',
          prefs.glowLevel === 'high' ? 'animate-pulse' : '' 
        )} 
      />

      {/* Contenido (si lo hay) */}
      <div className="relative z-10 w-full h-full">{children}</div>
    </div>
  );
};

const fs = require('fs');
const path = require('path');

const uiDir = path.join(__dirname, 'src/components/ui');
const srcDir = path.join(__dirname, 'src');

// Get all UI component files
const uiFiles = fs.readdirSync(uiDir)
  .filter(f => f.endsWith('.tsx') || f.endsWith('.ts'))
  .map(f => f.replace(/\.(tsx|ts)$/, ''));

// Read all source files
function getAllSourceFiles(dir, files = []) {
  const entries = fs.readdirSync(dir, { withFileTypes: true });
  for (const entry of entries) {
    if (entry.isDirectory() && !entry.name.startsWith('.') && entry.name !== 'node_modules') {
      getAllSourceFiles(path.join(dir, entry.name), files);
    } else if (entry.isFile() && (entry.name.endsWith('.tsx') || entry.name.endsWith('.ts') || entry.name.endsWith('.jsx') || entry.name.endsWith('.js'))) {
      files.push(path.join(dir, entry.name));
    }
  }
  return files;
}

const sourceFiles = getAllSourceFiles(srcDir);
const sourceContent = sourceFiles.map(f => fs.readFileSync(f, 'utf8')).join('\n');

// Check usage of each component
const unused = [];
const used = [];

for (const comp of uiFiles) {
  // Skip index files
  if (comp === 'index') continue;
  
  // Check for imports
  const patterns = [
    new RegExp(`from\\s+['\"].*ui/${comp}['\"]`, 'g'),
    new RegExp(`from\\s+['\"].*ui['\"].*\\b${comp}\\b`, 'g'),
    new RegExp(`import.*\\b${comp}\\b.*from.*ui`, 'g'),
  ];
  
  let found = false;
  for (const pattern of patterns) {
    if (pattern.test(sourceContent)) {
      found = true;
      break;
    }
  }
  
  if (found) {
    used.push(comp);
  } else {
    unused.push(comp);
  }
}

console.log('\n=== COMPONENTES UI UTILIZADOS ===');
console.log(`Total: ${used.length}`);
used.sort().forEach(c => console.log(`  ✓ ${c}`));

console.log('\n=== COMPONENTES UI NO UTILIZADOS (ZOMBIES) ===');
console.log(`Total: ${unused.length}`);
unused.sort().forEach(c => console.log(`  ✗ ${c}`));

// Save report
const report = {
  timestamp: new Date().toISOString(),
  totalComponents: uiFiles.length,
  used: used.length,
  unused: unused.length,
  unusedComponents: unused.sort(),
  usedComponents: used.sort()
};

fs.writeFileSync(
  path.join(__dirname, 'AUDIT_UI_COMPONENTS.json'),
  JSON.stringify(report, null, 2)
);

console.log('\n✓ Reporte guardado en AUDIT_UI_COMPONENTS.json');

