/**
 * =====================================================
 * ALERT CONFIG PANEL
 * =====================================================
 * Panel de configuración de alertas y umbrales
 * Fecha: 2025-10-29
 * Versión: v3.4.1
 * =====================================================
 */

import React, { useState, useEffect } from 'react';
import {
  BellIcon,
  ExclamationTriangleIcon,
  CheckCircleIcon,
  XMarkIcon,
  PlusIcon
} from '@heroicons/react/24/outline';
import { Button } from '@/shared/ui/Button';
import { Input } from '@/shared/ui/Input';
import { Label } from '@/components/ui/label';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Switch } from '@/components/ui/switch';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@/shared/ui/Modal';
import { logger } from '@/lib/logger';
import errorAlertService, { AlertRule } from '@/services/ErrorAlertService';
import { useToast } from '@/hooks/useToast';
import { safeGetItem, safeSetItem } from '@/utils/safeLocalStorage';
// performanceMonitoring - preparado para uso futuro en configuración avanzada
// import performanceMonitoring from '@/services/PerformanceMonitoringService';

// =====================================================
// INTERFACES
// =====================================================

interface AlertConfig {
  id: string;
  name: string;
  type: 'performance' | 'error';
  enabled: boolean;
  conditions: {
    metric?: string;
    severity?: 'low' | 'medium' | 'high' | 'critical';
    threshold?: number;
    operator?: '>' | '<' | '=' | '>=' | '<=';
  };
  actions: {
    notification: boolean;
    email: boolean;
    console: boolean;
  };
}

// =====================================================
// PRESETS DE CONFIGURACIÓN
// =====================================================

const ALERT_PRESETS: AlertConfig[] = [
  {
    id: 'performance-critical',
    name: 'Performance Crítico',
    type: 'performance',
    enabled: true,
    conditions: {
      metric: 'pageLoadTime',
      threshold: 4000,
      operator: '>='
    },
    actions: {
      notification: true,
      email: false,
      console: true
    }
  },
  {
    id: 'error-critical',
    name: 'Error Crítico',
    type: 'error',
    enabled: true,
    conditions: {
      severity: 'critical'
    },
    actions: {
      notification: true,
      email: false,
      console: true
    }
  },
  {
    id: 'performance-warning',
    name: 'Performance Advertencia',
    type: 'performance',
    enabled: true,
    conditions: {
      metric: 'pageLoadTime',
      threshold: 2000,
      operator: '>='
    },
    actions: {
      notification: false,
      email: false,
      console: true
    }
  },
  {
    id: 'memory-high',
    name: 'Uso de Memoria Alto',
    type: 'performance',
    enabled: true,
    conditions: {
      metric: 'memoryUsage',
      threshold: 200,
      operator: '>='
    },
    actions: {
      notification: true,
      email: false,
      console: true
    }
  }
];

// =====================================================
// COMPONENTE PRINCIPAL
// =====================================================

export const AlertConfigPanel: React.FC = () => {
  const [configs, setConfigs] = useState<AlertConfig[]>(ALERT_PRESETS);
  const [activeTab, setActiveTab] = useState<'performance' | 'error'>('performance');
  const [editingConfig, setEditingConfig] = useState<AlertConfig | null>(null);
  const [showAddDialog, setShowAddDialog] = useState(false);
  const [newConfig, setNewConfig] = useState<Partial<AlertConfig>>({
    name: '',
    type: 'performance',
    enabled: true,
    conditions: {},
    actions: {
      notification: true,
      email: false,
      console: true
    }
  });
  const { toast } = useToast();

  useEffect(() => {
    loadConfigs();
    logger.info('📋 Alert Config Panel loaded');
  }, []);

  // =====================================================
  // MÉTODOS PRINCIPALES
  // =====================================================

  const loadConfigs = () => {
    try {
      const saved = safeGetItem<AlertConfig[]>('alert-configs', { validate: false, defaultValue: null });
      if (saved && Array.isArray(saved)) {
        setConfigs(saved);
        applyConfigs(saved);
      } else {
        applyConfigs(ALERT_PRESETS);
      }
    } catch (error) {
      logger.error('Error loading alert configs:', { error: String(error) });
    }
  };

  const saveConfigs = (newConfigs: AlertConfig[]) => {
    try {
      safeSetItem('alert-configs', newConfigs, { validate: false, sanitize: true });
      setConfigs(newConfigs);
      applyConfigs(newConfigs);
      logger.info('✅ Alert configs saved');
    } catch (error) {
      logger.error('Error saving alert configs:', { error: String(error) });
    }
  };

  const applyConfigs = (configs: AlertConfig[]) => {
    // Aplicar configuraciones a los servicios
    configs.forEach((config) => {
      if (config.type === 'error' && config.enabled) {
        // Configurar reglas de error
        const rule: AlertRule = {
          id: config.id,
          name: config.name,
          enabled: config.enabled,
          condition: (alert) => {
            if (config.conditions.severity) {
              return alert.severity === config.conditions.severity;
            }
            return false;
          },
          actions: []
        };

        if (config.actions.console) {
          rule.actions.push({ type: 'console', level: 'error' });
        }

        if (config.actions.notification) {
          rule.actions.push({
            type: 'notification',
            title: `Alerta: ${config.name}`,
            body: 'Se ha detectado una alerta crítica'
          });
        }

        // Agregar regla al servicio
        errorAlertService.addRule(rule);
      }
    });
  };

  const toggleConfig = (id: string) => {
    const newConfigs = configs.map((c) =>
      c.id === id ? { ...c, enabled: !c.enabled } : c
    );
    saveConfigs(newConfigs);
  };

  const deleteConfig = (id: string) => {
    const newConfigs = configs.filter((c) => c.id !== id);
    saveConfigs(newConfigs);
  };

  const addConfig = () => {
    if (!newConfig.name || !newConfig.type) {
      toast({
        title: "Error",
        description: "Por favor completa todos los campos requeridos",
        variant: "destructive"
      });
      return;
    }

    if (editingConfig) {
      // Modo edición
      const updatedConfig: AlertConfig = {
        ...editingConfig,
        name: newConfig.name!,
        type: newConfig.type!,
        enabled: newConfig.enabled ?? true,
        conditions: newConfig.conditions || {},
        actions: newConfig.actions || {
          notification: true,
          email: false,
          console: true
        }
      };
      updateConfig(updatedConfig);
    } else {
      // Modo creación
      const config: AlertConfig = {
        id: `custom-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
        name: newConfig.name!,
        type: newConfig.type!,
        enabled: newConfig.enabled ?? true,
        conditions: newConfig.conditions || {},
        actions: newConfig.actions || {
          notification: true,
          email: false,
          console: true
        }
      };

      const newConfigs = [...configs, config];
      saveConfigs(newConfigs);
      toast({
        title: "Éxito",
        description: "Alerta creada exitosamente"
      });
    }

    setShowAddDialog(false);
    setEditingConfig(null);
    setNewConfig({
      name: '',
      type: 'performance',
      enabled: true,
      conditions: {},
      actions: {
        notification: true,
        email: false,
        console: true
      }
    });
  };

  const updateConfig = (config: AlertConfig) => {
    const newConfigs = configs.map((c) => (c.id === config.id ? config : c));
    saveConfigs(newConfigs);
    setEditingConfig(null);
    toast({
      title: "Éxito",
      description: "Alerta actualizada exitosamente"
    });
  };

  const testAlert = (config: AlertConfig) => {
    logger.info(`🧪 Testing alert: ${config.name}`);

    if (config.type === 'error') {
      errorAlertService.createAlert({
        severity: config.conditions.severity || 'medium',
        category: 'unknown',
        message: `TEST: ${config.name}`,
        error: 'Test alert triggered manually'
      });
    }

    if (config.actions.notification && typeof window !== 'undefined' && 'Notification' in window) {
      if (Notification.permission === 'granted') {
        new Notification(`Test: ${config.name}`, {
          body: 'Esta es una alerta de prueba',
          icon: '/icon.png'
        });
      } else {
        alert(`Alerta de prueba: ${config.name}`);
      }
    }
  };

  // =====================================================
  // RENDERIZADO
  // =====================================================

  const filteredConfigs = configs.filter((c) => c.type === activeTab);

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-2xl font-bold text-white">Configuración de Alertas</h2>
          <p className="text-gray-400 mt-1">
            Configura umbrales y acciones para las alertas del sistema
          </p>
        </div>
        <Button
          onClick={() => setShowAddDialog(true)}
          className="bg-blue-600 hover:bg-blue-700 text-white"
        >
          <PlusIcon className="h-4 w-4 mr-2" />
          Nueva Alerta
        </Button>
      </div>

      {/* Tabs */}
      <div className="border-b border-gray-700">
        <div className="flex space-x-4">
          <button
            onClick={() => setActiveTab('performance')}
            className={`pb-3 px-1 border-b-2 transition-colors ${
              activeTab === 'performance'
                ? 'border-blue-500 text-blue-400'
                : 'border-transparent text-gray-400 hover:text-white'
            }`}
          >
            <span className="flex items-center space-x-2">
              <CheckCircleIcon className="h-5 w-5" />
              <span>Performance</span>
            </span>
          </button>
          <button
            onClick={() => setActiveTab('error')}
            className={`pb-3 px-1 border-b-2 transition-colors ${
              activeTab === 'error'
                ? 'border-red-500 text-red-400'
                : 'border-transparent text-gray-400 hover:text-white'
            }`}
          >
            <span className="flex items-center space-x-2">
              <ExclamationTriangleIcon className="h-5 w-5" />
              <span>Errores</span>
            </span>
          </button>
        </div>
      </div>

      {/* Lista de Configuraciones */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
        {filteredConfigs.map((config) => (
          <div
            key={config.id}
            className={`bg-slate-700/50 rounded-lg border p-4 transition-all ${
              config.enabled
                ? 'border-slate-600 hover:border-blue-500'
                : 'border-slate-700/50 opacity-60'
            }`}
          >
            <div className="flex items-start justify-between mb-3">
              <div className="flex items-center space-x-3">
                <div
                  className={`w-10 h-10 rounded-lg flex items-center justify-center ${
                    config.type === 'performance'
                      ? 'bg-blue-500/20'
                      : 'bg-red-500/20'
                  }`}
                >
                  {config.type === 'performance' ? (
                    <CheckCircleIcon className="h-6 w-6 text-blue-400" />
                  ) : (
                    <ExclamationTriangleIcon className="h-6 w-6 text-red-400" />
                  )}
                </div>
                <div>
                  <h3 className="text-white font-semibold">{config.name}</h3>
                  <p className="text-sm text-gray-400">
                    {config.type === 'performance' && config.conditions.metric
                      ? `${config.conditions.metric} ${config.conditions.operator} ${config.conditions.threshold}`
                      : `Severidad: ${config.conditions.severity}`}
                  </p>
                </div>
              </div>

              <label className="relative inline-flex items-center cursor-pointer">
                <input
                  type="checkbox"
                  checked={config.enabled}
                  onChange={() => toggleConfig(config.id)}
                  className="sr-only peer"
                  aria-label={`Activar/desactivar ${config.name}`}
                />
                <div className="w-11 h-6 bg-gray-700 peer-focus:outline-none peer-focus:ring-2 peer-focus:ring-blue-500 rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all peer-checked:bg-blue-600"></div>
              </label>
            </div>

            {/* Acciones Activas */}
            <div className="flex items-center space-x-2 mb-3 text-sm">
              <span className="text-gray-400">Acciones:</span>
              {config.actions.notification && (
                <span className="px-2 py-1 bg-purple-500/20 text-purple-300 rounded">
                  <BellIcon className="h-4 w-4 inline mr-1" />
                  Notificación
                </span>
              )}
              {config.actions.console && (
                <span className="px-2 py-1 bg-blue-500/20 text-blue-300 rounded">
                  Console
                </span>
              )}
            </div>

            {/* Botones de Acción */}
            <div className="flex items-center space-x-2">
              <Button
                onClick={() => testAlert(config)}
                variant="outline"
                size="sm"
                className="flex-1 text-gray-300 border-gray-600 hover:bg-gray-700"
              >
                🧪 Probar
              </Button>
              <Button
                onClick={() => {
                  setEditingConfig(config);
                  setNewConfig({
                    name: config.name,
                    type: config.type,
                    enabled: config.enabled,
                    conditions: config.conditions,
                    actions: config.actions
                  });
                  setShowAddDialog(true);
                }}
                variant="outline"
                size="sm"
                className="flex-1 text-gray-300 border-gray-600 hover:bg-gray-700"
              >
                ✏️ Editar
              </Button>
              <Button
                onClick={() => deleteConfig(config.id)}
                variant="outline"
                size="sm"
                className="text-red-400 border-red-600 hover:bg-red-900/20"
              >
                <XMarkIcon className="h-4 w-4" />
              </Button>
            </div>
          </div>
        ))}
      </div>

      {/* Empty State */}
      {filteredConfigs.length === 0 && (
        <div className="text-center py-12">
          <ExclamationTriangleIcon className="h-12 w-12 text-gray-500 mx-auto mb-3" />
          <p className="text-gray-400">No hay alertas configuradas para {activeTab}</p>
          <Button
            onClick={() => setShowAddDialog(true)}
            variant="outline"
            className="mt-4"
          >
            <PlusIcon className="h-4 w-4 mr-2" />
            Agregar Primera Alerta
          </Button>
        </div>
      )}

      {/* Dialog para Agregar/Editar Alerta */}
      <Dialog open={showAddDialog} onOpenChange={setShowAddDialog}>
        <DialogContent className="bg-slate-800 text-white border-slate-700 max-w-2xl max-h-[90vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle>
              {editingConfig ? 'Editar Alerta' : 'Nueva Alerta'}
            </DialogTitle>
            <DialogDescription className="text-gray-400">
              {editingConfig
                ? 'Modifica la configuración de la alerta'
                : 'Crea una nueva alerta personalizada para monitorear el sistema'
              }
            </DialogDescription>
          </DialogHeader>

          <div className="space-y-4 py-4">
            {/* Nombre */}
            <div className="space-y-2">
              <Label htmlFor="alert-name">Nombre de la Alerta</Label>
              <Input
                id="alert-name"
                value={newConfig.name || ''}
                onChange={(e) => setNewConfig({ ...newConfig, name: e.target.value })}
                placeholder="Ej: Tiempo de carga crítico"
                className="bg-slate-700 border-slate-600 text-white"
              />
            </div>

            {/* Tipo */}
            <div className="space-y-2">
              <Label htmlFor="alert-type">Tipo de Alerta</Label>
              <Select
                value={newConfig.type}
                onValueChange={(value) => setNewConfig({ ...newConfig, type: value as 'performance' | 'error' })}
              >
                <SelectTrigger className="bg-slate-700 border-slate-600 text-white">
                  <SelectValue placeholder="Selecciona el tipo" />
                </SelectTrigger>
                <SelectContent className="bg-slate-800 border-slate-700">
                  <SelectItem value="performance">Performance</SelectItem>
                  <SelectItem value="error">Error</SelectItem>
                </SelectContent>
              </Select>
            </div>

            {/* Condiciones para Performance */}
            {newConfig.type === 'performance' && (
              <>
                <div className="space-y-2">
                  <Label htmlFor="alert-metric">Métrica</Label>
                  <Select
                    value={newConfig.conditions?.metric || ''}
                    onValueChange={(value) => setNewConfig({
                      ...newConfig,
                      conditions: { ...newConfig.conditions, metric: value }
                    })}
                  >
                    <SelectTrigger className="bg-slate-700 border-slate-600 text-white">
                      <SelectValue placeholder="Selecciona la métrica" />
                    </SelectTrigger>
                    <SelectContent className="bg-slate-800 border-slate-700">
                      <SelectItem value="pageLoadTime">Tiempo de Carga de Página</SelectItem>
                      <SelectItem value="apiResponseTime">Tiempo de Respuesta API</SelectItem>
                      <SelectItem value="memoryUsage">Uso de Memoria</SelectItem>
                      <SelectItem value="cpuUsage">Uso de CPU</SelectItem>
                    </SelectContent>
                  </Select>
                </div>

                <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-2">
                    <Label htmlFor="alert-operator">Operador</Label>
                    <Select
                      value={newConfig.conditions?.operator || '>='}
                      onValueChange={(value) => setNewConfig({
                        ...newConfig,
                        conditions: { ...newConfig.conditions, operator: value as '>' | '<' | '=' | '>=' | '<=' }
                      })}
                    >
                      <SelectTrigger className="bg-slate-700 border-slate-600 text-white">
                        <SelectValue />
                      </SelectTrigger>
                      <SelectContent className="bg-slate-800 border-slate-700">
                        <SelectItem value=">">Mayor que (&gt;)</SelectItem>
                        <SelectItem value="<">Menor que (&lt;)</SelectItem>
                        <SelectItem value=">=">Mayor o igual (&gt;=)</SelectItem>
                        <SelectItem value="<=">Menor o igual (&lt;=)</SelectItem>
                        <SelectItem value="=">Igual (=)</SelectItem>
                      </SelectContent>
                    </Select>
                  </div>

                  <div className="space-y-2">
                    <Label htmlFor="alert-threshold">Umbral</Label>
                    <Input
                      id="alert-threshold"
                      type="number"
                      value={newConfig.conditions?.threshold || ''}
                      onChange={(e) => setNewConfig({
                        ...newConfig,
                        conditions: { ...newConfig.conditions, threshold: Number(e.target.value) }
                      })}
                      placeholder="1000"
                      className="bg-slate-700 border-slate-600 text-white"
                    />
                  </div>
                </div>
              </>
            )}

            {/* Condiciones para Error */}
            {newConfig.type === 'error' && (
              <div className="space-y-2">
                <Label htmlFor="alert-severity">Severidad</Label>
                <Select
                  value={newConfig.conditions?.severity || 'medium'}
                  onValueChange={(value) => setNewConfig({
                    ...newConfig,
                    conditions: { ...newConfig.conditions, severity: value as 'low' | 'medium' | 'high' | 'critical' }
                  })}
                >
                  <SelectTrigger className="bg-slate-700 border-slate-600 text-white">
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent className="bg-slate-800 border-slate-700">
                    <SelectItem value="low">Baja</SelectItem>
                    <SelectItem value="medium">Media</SelectItem>
                    <SelectItem value="high">Alta</SelectItem>
                    <SelectItem value="critical">Crítica</SelectItem>
                  </SelectContent>
                </Select>
              </div>
            )}

            {/* Acciones */}
            <div className="space-y-3 border-t border-slate-700 pt-4">
              <Label>Acciones a Ejecutar</Label>
              <div className="flex items-center justify-between">
                <span className="text-sm text-gray-300">Notificación del navegador</span>
                <Switch
                  checked={newConfig.actions?.notification ?? true}
                  onCheckedChange={(checked) => setNewConfig({
                    ...newConfig,
                    actions: {
                      notification: checked,
                      console: newConfig.actions?.console ?? true,
                      email: newConfig.actions?.email ?? false
                    }
                  })}
                />
              </div>
              <div className="flex items-center justify-between">
                <span className="text-sm text-gray-300">Registro en consola</span>
                <Switch
                  checked={newConfig.actions?.console ?? true}
                  onCheckedChange={(checked) => setNewConfig({
                    ...newConfig,
                    actions: {
                      notification: newConfig.actions?.notification ?? true,
                      console: checked,
                      email: newConfig.actions?.email ?? false
                    }
                  })}
                />
              </div>
              <div className="flex items-center justify-between">
                <span className="text-sm text-gray-300">Enviar por email</span>
                <Switch
                  checked={newConfig.actions?.email ?? false}
                  onCheckedChange={(checked) => setNewConfig({
                    ...newConfig,
                    actions: {
                      notification: newConfig.actions?.notification ?? true,
                      console: newConfig.actions?.console ?? true,
                      email: checked
                    }
                  })}
                />
              </div>
            </div>

            {/* Estado */}
            <div className="flex items-center justify-between border-t border-slate-700 pt-4">
              <span className="text-sm text-gray-300">Alerta Habilitada</span>
              <Switch
                checked={newConfig.enabled ?? true}
                onCheckedChange={(checked) => setNewConfig({ ...newConfig, enabled: checked })}
              />
            </div>
          </div>

          <DialogFooter>
            <Button
              variant="outline"
              onClick={() => {
                setShowAddDialog(false);
                setEditingConfig(null);
                setNewConfig({
                  name: '',
                  type: 'performance',
                  enabled: true,
                  conditions: {},
                  actions: {
                    notification: true,
                    email: false,
                    console: true
                  }
                });
              }}
              className="text-gray-300 border-slate-600 hover:bg-slate-700"
            >
              Cancelar
            </Button>
            <Button
              onClick={addConfig}
              className="bg-blue-600 hover:bg-blue-700 text-white"
            >
              {editingConfig ? 'Actualizar' : 'Crear'} Alerta
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
};

export default AlertConfigPanel;

/**
 * =====================================================
 * ANALYTICS DASHBOARD
 * =====================================================
 * Dashboard en tiempo real para monitoreo de métricas y errores
 * Fecha: 2025-10-28
 * Versión: v3.4.1
 * =====================================================
 */

import React, { useState, useEffect } from 'react';
import {
  ChartBarIcon,
  ExclamationTriangleIcon,
  CheckCircleIcon,
  ClockIcon,
  ServerIcon,
  SignalIcon,
  ShieldCheckIcon
} from '@heroicons/react/24/outline';

import performanceMonitoring from '@/services/PerformanceMonitoringService';
import errorAlertService from '@/services/ErrorAlertService';
import { logger } from '@/lib/logger';
import { AlertConfigPanel } from './AlertConfigPanel';
import { ExportButton } from './ExportButton';
import { DesktopNotificationSettings } from './DesktopNotificationSettings';
import { ModerationMetricsPanel } from './ModerationMetrics';
import { HistoricalCharts } from './HistoricalCharts';
import { WebhookConfigPanel } from './WebhookConfigPanel';
// ExportData se usa como tipo en props de ExportButton, no necesita import directo

// =====================================================
// INTERFACES
// =====================================================

interface DashboardMetrics {
  performance: {
    avgLoadTime: number;
    avgInteractionTime: number;
    totalRequests: number;
    failedRequests: number;
    memoryUsage: number;
  };
  errors: {
    total: number;
    bySeverity: {
      low: number;
      medium: number;
      high: number;
      critical: number;
    };
    byCategory: {
      frontend: number;
      backend: number;
      network: number;
      database: number;
      auth: number;
      unknown: number;
    };
    resolved: number;
    unresolved: number;
    last24Hours: number;
  };
  webVitals: {
    lcp?: number;
    fid?: number;
    cls?: number;
    fcp?: number;
    ttfb?: number;
  };
}

// =====================================================
// COMPONENT
// =====================================================

export const AnalyticsDashboard: React.FC = () => {
  const [metrics, setMetrics] = useState<DashboardMetrics>({
    performance: {
      avgLoadTime: 0,
      avgInteractionTime: 0,
      totalRequests: 0,
      failedRequests: 0,
      memoryUsage: 0
    },
    errors: {
      total: 0,
      bySeverity: {
        low: 0,
        medium: 0,
        high: 0,
        critical: 0
      },
      byCategory: {
        frontend: 0,
        backend: 0,
        network: 0,
        database: 0,
        auth: 0,
        unknown: 0
      },
      resolved: 0,
      unresolved: 0,
      last24Hours: 0
    },
    webVitals: {}
  });

  const [refreshInterval, setRefreshInterval] = useState<number>(5000);
  const [autoRefresh, setAutoRefresh] = useState<boolean>(true);
  const [activeTab, setActiveTab] = useState<'overview' | 'config' | 'moderation' | 'historical'>('overview');

  // =====================================================
  // EFFECTS
  // =====================================================

  useEffect(() => {
    loadMetrics();

    if (autoRefresh) {
      const interval = setInterval(loadMetrics, refreshInterval);
      return () => clearInterval(interval);
    }
  }, [autoRefresh, refreshInterval]);

  // =====================================================
  // FUNCTIONS
  // =====================================================

  const loadMetrics = () => {
    try {
      // Load performance metrics
      const perfReport = performanceMonitoring.generateReport(60);
      const webVitals = performanceMonitoring.getWebVitals();

      // Load error statistics
      const errorStats = errorAlertService.getStatistics();

      setMetrics({
        performance: perfReport.summary,
        errors: errorStats,
        webVitals
      });

      logger.debug('Dashboard metrics updated');
    } catch (error) {
      logger.error('Error loading dashboard metrics:', { error: String(error) });
    }
  };

  // =====================================================
  // HELPER COMPONENTS
  // =====================================================

  const SimpleBarChart = ({ data, max }: { data: Array<{ label: string; value: number; color: string }>; max: number }) => (
    <div className="space-y-3">
      {data.map((item) => (
        <div key={item.label}>
          <div className="flex justify-between mb-1">
            <span className="text-sm text-gray-600 dark:text-gray-400">{item.label}</span>
            <span className="text-sm font-semibold text-white">{item.value}</span>
          </div>
          <div className="w-full bg-gray-200 dark:bg-gray-700 rounded-full h-3">
            {/* ⚠️ EXCEPCIÓN LEGÍTIMA CSS INLINE - Ancho y color dinámicos calculados en runtime */}
            <div
              className="h-3 rounded-full transition-all"
              style={{
                width: `${Math.min((item.value / max) * 100, 100)}%`,
                backgroundColor: item.color
              }}
            ></div>
          </div>
        </div>
      ))}
    </div>
  );

  // =====================================================
  // RENDER
  // =====================================================

  return (
    <div className="p-6 space-y-6 bg-gray-50 dark:bg-gray-900 min-h-screen">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold text-white">
            📊 Analytics Dashboard
          </h1>
          <p className="text-gray-600 dark:text-gray-400 mt-1">
            Monitoreo en tiempo real de performance y errores
          </p>
        </div>

        <div className="flex items-center space-x-4">
          <label className="flex items-center space-x-2">
            <input
              type="checkbox"
              checked={autoRefresh}
              onChange={(e) => setAutoRefresh(e.target.checked)}
              className="rounded border-gray-300 text-blue-600 focus:ring-blue-500"
            />
            <span className="text-sm text-gray-700 dark:text-gray-300">Auto Refresh</span>
          </label>

          <select
            value={refreshInterval}
            onChange={(e) => setRefreshInterval(Number(e.target.value))}
            title="Intervalo de actualización automática"
            className="px-3 py-2 border border-white/20 rounded-lg text-sm bg-white/10 backdrop-blur-sm text-white focus:outline-none focus:ring-2 focus:ring-purple-400/50 transition-all duration-300"
          >
            <option value={1000}>1s</option>
            <option value={5000}>5s</option>
            <option value={10000}>10s</option>
            <option value={30000}>30s</option>
          </select>

          <button
            onClick={loadMetrics}
            className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors"
          >
            🔄 Refresh Now
          </button>

          {/* Botón de Exportación */}
          <ExportButton
            data={{
              metrics: performanceMonitoring.getMetrics({}),
              alerts: errorAlertService.getAlerts({}),
              report: performanceMonitoring.generateReport(24), // Últimas 24 horas
              metadata: {
                exportDate: new Date().toISOString(),
                appVersion: '3.4.1',
                totalRecords: performanceMonitoring.getMetrics({}).length + errorAlertService.getAlerts({}).length
              }
            }}
            className="bg-green-600 hover:bg-green-700 text-white border-green-600"
          />
        </div>
      </div>

      {/* Tabs */}
      <div className="border-b border-gray-200 dark:border-gray-700">
        <div className="flex space-x-4">
          <button
            onClick={() => setActiveTab('overview')}
            className={`pb-3 px-1 border-b-2 transition-colors ${
              activeTab === 'overview'
                ? 'border-blue-500 text-blue-600 dark:text-blue-400'
                : 'border-transparent text-gray-500 dark:text-gray-400 hover:text-gray-700 dark:hover:text-gray-300'
            }`}
          >
            <span className="flex items-center space-x-2">
              <ChartBarIcon className="h-5 w-5" />
              <span className="font-medium">Overview</span>
            </span>
          </button>
          
          <button
            onClick={() => setActiveTab('moderation')}
            className={`pb-3 px-1 border-b-2 transition-colors ${
              activeTab === 'moderation'
                ? 'border-blue-500 text-blue-600 dark:text-blue-400'
                : 'border-transparent text-gray-500 dark:text-gray-400 hover:text-gray-700 dark:hover:text-gray-300'
            }`}
          >
            <span className="flex items-center space-x-2">
              <ShieldCheckIcon className="h-5 w-5" />
              <span className="font-medium">Moderación</span>
            </span>
          </button>
          
          <button
            onClick={() => setActiveTab('historical')}
            className={`pb-3 px-1 border-b-2 transition-colors ${
              activeTab === 'historical'
                ? 'border-blue-500 text-blue-600 dark:text-blue-400'
                : 'border-transparent text-gray-500 dark:text-gray-400 hover:text-gray-700 dark:hover:text-gray-300'
            }`}
          >
            <span className="flex items-center space-x-2">
              <SignalIcon className="h-5 w-5" />
              <span className="font-medium">Histórico</span>
            </span>
          </button>
          
          <button
            onClick={() => setActiveTab('config')}
            className={`pb-3 px-1 border-b-2 transition-colors ${
              activeTab === 'config'
                ? 'border-blue-500 text-blue-600 dark:text-blue-400'
                : 'border-transparent text-gray-500 dark:text-gray-400 hover:text-gray-700 dark:hover:text-gray-300'
            }`}
          >
            <span className="flex items-center space-x-2">
              <CheckCircleIcon className="h-5 w-5" />
              <span className="font-medium">Configuración</span>
            </span>
          </button>
        </div>
      </div>

      {/* Tab Content */}
      {activeTab === 'overview' && (
        <>
          {/* Metrics Cards */}
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        {/* Avg Load Time */}
        <div className="bg-gradient-to-br from-purple-900/90 via-purple-800/90 to-blue-900/90 backdrop-blur-xl p-6 rounded-xl shadow-2xl border border-white/20 hover:border-white/30 transition-all duration-300">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm text-white/70 font-medium">⚡ Avg Load Time</p>
              <p className="text-3xl font-bold text-white mt-2">
                {metrics.performance.avgLoadTime}ms
              </p>
            </div>
            <ClockIcon className="w-12 h-12 text-blue-500" />
          </div>
          <div className="mt-4">
            <div className="w-full bg-gray-200 dark:bg-gray-700 rounded-full h-2">
              {/* ⚠️ EXCEPCIÓN LEGÍTIMA CSS INLINE - Ancho dinámico basado en métricas */}
              <div
                className="bg-blue-600 h-2 rounded-full transition-all"
                style={{
                  width: `${Math.min((metrics.performance.avgLoadTime / 4000) * 100, 100)}%`
                }}
              ></div>
            </div>
          </div>
        </div>

        {/* Total Requests */}
        <div className="bg-gradient-to-br from-purple-900/90 via-purple-800/90 to-blue-900/90 backdrop-blur-xl p-6 rounded-xl shadow-2xl border border-white/20 hover:border-white/30 transition-all duration-300">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm text-white/70 font-medium">📊 Total Requests</p>
              <p className="text-3xl font-bold text-white mt-2">
                {metrics.performance.totalRequests}
              </p>
            </div>
            <ServerIcon className="w-12 h-12 text-green-500" />
          </div>
          <p className="text-sm text-gray-500 dark:text-gray-400 mt-4">
            {metrics.performance.failedRequests} failed
          </p>
        </div>

        {/* Memory Usage */}
        <div className="bg-gradient-to-br from-purple-900/90 via-purple-800/90 to-blue-900/90 backdrop-blur-xl p-6 rounded-xl shadow-2xl border border-white/20 hover:border-white/30 transition-all duration-300">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm text-white/70 font-medium">💾 Memory Usage</p>
              <p className="text-3xl font-bold text-white mt-2">
                {metrics.performance.memoryUsage}MB
              </p>
            </div>
            <SignalIcon className="w-12 h-12 text-purple-500" />
          </div>
          <div className="mt-4">
            <div className="w-full bg-gray-200 dark:bg-gray-700 rounded-full h-2">
              {/* ⚠️ EXCEPCIÓN LEGÍTIMA CSS INLINE - Ancho dinámico basado en uso de memoria */}
              <div
                className="bg-purple-600 h-2 rounded-full transition-all"
                style={{
                  width: `${Math.min((metrics.performance.memoryUsage / 200) * 100, 100)}%`
                }}
              ></div>
            </div>
          </div>
        </div>

        {/* Error Status */}
        <div className="bg-gradient-to-br from-purple-900/90 via-purple-800/90 to-blue-900/90 backdrop-blur-xl p-6 rounded-xl shadow-2xl border border-white/20 hover:border-white/30 transition-all duration-300">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm text-white/70 font-medium">🚨 Unresolved Errors</p>
              <p className="text-3xl font-bold text-white mt-2">
                {metrics.errors.unresolved}
              </p>
            </div>
            <ExclamationTriangleIcon
              className={`w-12 h-12 ${
                metrics.errors.unresolved > 0 ? 'text-red-500' : 'text-green-500'
              }`}
            />
          </div>
          <p className="text-sm text-gray-500 dark:text-gray-400 mt-4">
            {metrics.errors.bySeverity.critical} critical, {metrics.errors.bySeverity.high} high
          </p>
        </div>
      </div>

      {/* Charts Row */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Performance Metrics */}
        <div className="bg-gradient-to-br from-purple-900/90 via-purple-800/90 to-blue-900/90 backdrop-blur-xl p-6 rounded-xl shadow-2xl border border-white/20 hover:border-white/30 transition-all duration-300">
          <h3 className="text-lg font-semibold text-white mb-4">
            📈 Performance
          </h3>
          <SimpleBarChart
            data={[
              { label: 'Load Time', value: metrics.performance.avgLoadTime, color: '#3b82f6' },
              { label: 'Interaction', value: metrics.performance.avgInteractionTime, color: '#10b981' },
              { label: 'Memory (MB)', value: metrics.performance.memoryUsage, color: '#8b5cf6' }
            ]}
            max={Math.max(metrics.performance.avgLoadTime, metrics.performance.avgInteractionTime, metrics.performance.memoryUsage * 10)}
          />
        </div>

        {/* Errors by Severity */}
        <div className="bg-gradient-to-br from-purple-900/90 via-purple-800/90 to-blue-900/90 backdrop-blur-xl p-6 rounded-xl shadow-2xl border border-white/20 hover:border-white/30 transition-all duration-300">
          <h3 className="text-lg font-semibold text-white mb-4">
            🚨 Errors by Severity
          </h3>
          <SimpleBarChart
            data={[
              { label: 'Critical', value: metrics.errors.bySeverity.critical, color: '#ef4444' },
              { label: 'High', value: metrics.errors.bySeverity.high, color: '#f97316' },
              { label: 'Medium', value: metrics.errors.bySeverity.medium, color: '#eab308' },
              { label: 'Low', value: metrics.errors.bySeverity.low, color: '#22c55e' }
            ]}
            max={Math.max(...Object.values(metrics.errors.bySeverity)) || 1}
          />
        </div>

        {/* Web Vitals */}
        <div className="bg-gradient-to-br from-purple-900/90 via-purple-800/90 to-blue-900/90 backdrop-blur-xl p-6 rounded-xl shadow-2xl border border-white/20 hover:border-white/30 transition-all duration-300">
          <h3 className="text-lg font-semibold text-white mb-4">
            ⚡ Web Vitals
          </h3>
          <SimpleBarChart
            data={[
              { label: 'LCP', value: metrics.webVitals.lcp || 0, color: '#10b981' },
              { label: 'FCP', value: metrics.webVitals.fcp || 0, color: '#06b6d4' }
            ]}
            max={4000}
          />
        </div>
      </div>

      {/* Recent Alerts */}
      <div className="bg-gradient-to-br from-purple-900/90 via-purple-800/90 to-blue-900/90 backdrop-blur-xl p-6 rounded-xl shadow-2xl border border-white/20 hover:border-white/30 transition-all duration-300">
        <h3 className="text-lg font-semibold text-white mb-4">
          🔔 Recent Alerts (Last 24h)
        </h3>
        <div className="space-y-3">
          {errorAlertService
            .getAlerts({
              since: new Date(Date.now() - 24 * 60 * 60 * 1000),
              resolved: false
            })
            .slice(0, 5)
            .map((alert) => (
              <div
                key={alert.id}
                className="flex items-center justify-between p-4 bg-gray-50 dark:bg-gray-900 rounded-lg"
              >
                <div className="flex items-center space-x-3">
                  {alert.severity === 'critical' && (
                    <ExclamationTriangleIcon className="w-6 h-6 text-red-500" />
                  )}
                  {alert.severity === 'high' && (
                    <ExclamationTriangleIcon className="w-6 h-6 text-orange-500" />
                  )}
                  {alert.severity === 'medium' && (
                    <ChartBarIcon className="w-6 h-6 text-yellow-500" />
                  )}
                  {alert.severity === 'low' && (
                    <CheckCircleIcon className="w-6 h-6 text-green-500" />
                  )}

                  <div>
                    <p className="text-sm font-medium text-white">
                      {alert.message}
                    </p>
                    <p className="text-xs text-gray-500 dark:text-gray-400">
                      {alert.category} • {new Date(alert.timestamp).toLocaleTimeString()}
                    </p>
                  </div>
                </div>

                <button
                  onClick={() => errorAlertService.resolveAlert(alert.id)}
                  className="px-3 py-1 text-xs bg-green-600 text-white rounded hover:bg-green-700"
                >
                  Resolve
                </button>
              </div>
            ))}

          {errorAlertService.getAlerts({ resolved: false }).length === 0 && (
            <div className="text-center py-8 text-gray-500 dark:text-gray-400">
              ✅ No unresolved alerts
            </div>
          )}
        </div>
      </div>
        </>
      )}

      {/* Moderation Tab */}
      {activeTab === 'moderation' && (
        <ModerationMetricsPanel refreshInterval={refreshInterval / 1000} />
      )}

      {/* Historical Tab */}
      {activeTab === 'historical' && (
        <div className="mt-6">
          <HistoricalCharts refreshInterval={refreshInterval / 1000} />
        </div>
      )}

      {/* Config Tab */}
      {activeTab === 'config' && (
        <div className="mt-6 space-y-6">
          <AlertConfigPanel />
          <DesktopNotificationSettings />
          <WebhookConfigPanel />
        </div>
      )}
    </div>
  );
};

export default AnalyticsDashboard;

/**
 * =====================================================
 * HISTORICAL CHARTS COMPONENT
 * =====================================================
 * Gráficos históricos avanzados con Recharts
 * Fecha: 2025-10-30
 * Versión: v3.4.1
 * =====================================================
 */

import React, { useState, useEffect } from 'react';
import {
  LineChart,
  Line,
  AreaChart,
  Area,
  BarChart,
  Bar,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Legend,
  ResponsiveContainer,
  ComposedChart
} from 'recharts';

import historicalMetricsService, {
  type PerformanceTrendData,
  type ErrorTrendData,
  type WebVitalsTrendData,
  type ModerationTrendData
} from '@/services/HistoricalMetricsService';
import { logger } from '@/lib/logger';

// =====================================================
// INTERFACES
// =====================================================

interface HistoricalChartsProps {
  timeRange?: number; // en horas
  refreshInterval?: number; // en segundos
}

// =====================================================
// COMPONENT
// =====================================================

export const HistoricalCharts: React.FC<HistoricalChartsProps> = ({
  timeRange = 24,
  refreshInterval = 60
}) => {
  const [performanceData, setPerformanceData] = useState<PerformanceTrendData | null>(null);
  const [errorData, setErrorData] = useState<ErrorTrendData | null>(null);
  const [webVitalsData, setWebVitalsData] = useState<WebVitalsTrendData | null>(null);
  const [moderationData, setModerationData] = useState<ModerationTrendData | null>(null);
  const [loading, setLoading] = useState(true);
  const [selectedRange, setSelectedRange] = useState<number>(timeRange);

  // =====================================================
  // EFFECTS
  // =====================================================

  useEffect(() => {
    fetchAllData();

    const interval = setInterval(() => {
      fetchAllData();
    }, refreshInterval * 1000);

    return () => clearInterval(interval);
  }, [selectedRange, refreshInterval]);

  // =====================================================
  // FUNCTIONS
  // =====================================================

  const fetchAllData = async () => {
    try {
      const [perf, errors, vitals, moderation] = await Promise.all([
        historicalMetricsService.getPerformanceTrends({ hours: selectedRange }),
        historicalMetricsService.getErrorTrends({ hours: selectedRange }),
        historicalMetricsService.getWebVitalsTrends({ hours: selectedRange }),
        historicalMetricsService.getModerationTrends({ days: selectedRange > 24 ? 7 : 1 })
      ]);

      setPerformanceData(perf);
      setErrorData(errors);
      setWebVitalsData(vitals);
      setModerationData(moderation);
      setLoading(false);
    } catch (error) {
      logger.error('Error fetching historical data:', { error: String(error) });
      setLoading(false);
    }
  };

  // =====================================================
  // RENDER HELPERS
  // =====================================================

  const renderPerformanceChart = () => {
    if (!performanceData || performanceData.loadTime.length === 0) {
      return <EmptyState message="No hay datos de performance disponibles" />;
    }

    // Combinar datos para el gráfico
    const combinedData = performanceData.loadTime.map((item, index) => ({
      timestamp: item.label || item.timestamp,
      loadTime: item.value,
      interactionTime: performanceData.interactionTime[index]?.value || 0,
      memoryUsage: performanceData.memoryUsage[index]?.value || 0
    }));

    return (
      <div className="bg-white dark:bg-gray-800 p-6 rounded-xl shadow-lg border border-gray-200 dark:border-gray-700">
        <h3 className="text-lg font-semibold text-gray-900 dark:text-white mb-4">
          📈 Tendencias de Performance
        </h3>
        <ResponsiveContainer width="100%" height={300}>
          <LineChart data={combinedData}>
            <CartesianGrid strokeDasharray="3 3" stroke="#374151" />
            <XAxis 
              dataKey="timestamp" 
              stroke="#9CA3AF"
              style={{ fontSize: '12px' }}
            />
            <YAxis 
              stroke="#9CA3AF"
              style={{ fontSize: '12px' }}
            />
            <Tooltip
              contentStyle={{
                backgroundColor: '#1F2937',
                border: '1px solid #374151',
                borderRadius: '8px',
                color: '#F3F4F6'
              }}
            />
            <Legend />
            <Line
              type="monotone"
              dataKey="loadTime"
              name="Load Time (ms)"
              stroke="#3B82F6"
              strokeWidth={2}
              dot={false}
            />
            <Line
              type="monotone"
              dataKey="interactionTime"
              name="Interaction Time (ms)"
              stroke="#10B981"
              strokeWidth={2}
              dot={false}
            />
            <Line
              type="monotone"
              dataKey="memoryUsage"
              name="Memory (MB)"
              stroke="#8B5CF6"
              strokeWidth={2}
              dot={false}
            />
          </LineChart>
        </ResponsiveContainer>
      </div>
    );
  };

  const renderErrorChart = () => {
    if (!errorData || errorData.total.length === 0) {
      return <EmptyState message="No hay datos de errores disponibles" />;
    }

    // Combinar datos para el gráfico
    const combinedData = errorData.total.map((item, index) => ({
      timestamp: item.label || item.timestamp,
      total: item.value,
      critical: errorData.critical[index]?.value || 0,
      high: errorData.high[index]?.value || 0,
      medium: errorData.medium[index]?.value || 0,
      low: errorData.low[index]?.value || 0
    }));

    return (
      <div className="bg-white dark:bg-gray-800 p-6 rounded-xl shadow-lg border border-gray-200 dark:border-gray-700">
        <h3 className="text-lg font-semibold text-gray-900 dark:text-white mb-4">
          🚨 Distribución de Errores por Severidad
        </h3>
        <ResponsiveContainer width="100%" height={300}>
          <AreaChart data={combinedData}>
            <CartesianGrid strokeDasharray="3 3" stroke="#374151" />
            <XAxis 
              dataKey="timestamp" 
              stroke="#9CA3AF"
              style={{ fontSize: '12px' }}
            />
            <YAxis 
              stroke="#9CA3AF"
              style={{ fontSize: '12px' }}
            />
            <Tooltip
              contentStyle={{
                backgroundColor: '#1F2937',
                border: '1px solid #374151',
                borderRadius: '8px',
                color: '#F3F4F6'
              }}
            />
            <Legend />
            <Area
              type="monotone"
              dataKey="critical"
              name="Crítico"
              stackId="1"
              stroke="#EF4444"
              fill="#EF4444"
              fillOpacity={0.8}
            />
            <Area
              type="monotone"
              dataKey="high"
              name="Alto"
              stackId="1"
              stroke="#F97316"
              fill="#F97316"
              fillOpacity={0.8}
            />
            <Area
              type="monotone"
              dataKey="medium"
              name="Medio"
              stackId="1"
              stroke="#EAB308"
              fill="#EAB308"
              fillOpacity={0.8}
            />
            <Area
              type="monotone"
              dataKey="low"
              name="Bajo"
              stackId="1"
              stroke="#22C55E"
              fill="#22C55E"
              fillOpacity={0.8}
            />
          </AreaChart>
        </ResponsiveContainer>
      </div>
    );
  };

  const renderWebVitalsChart = () => {
    if (!webVitalsData || webVitalsData.lcp.length === 0) {
      return <EmptyState message="No hay datos de Web Vitals disponibles" />;
    }

    // Combinar datos para el gráfico
    const combinedData = webVitalsData.lcp.map((item, index) => ({
      timestamp: item.label || item.timestamp,
      lcp: item.value,
      fcp: webVitalsData.fcp[index]?.value || 0,
      fid: webVitalsData.fid[index]?.value || 0,
      ttfb: webVitalsData.ttfb[index]?.value || 0
    }));

    return (
      <div className="bg-white dark:bg-gray-800 p-6 rounded-xl shadow-lg border border-gray-200 dark:border-gray-700">
        <h3 className="text-lg font-semibold text-gray-900 dark:text-white mb-4">
          ⚡ Web Vitals - Core Metrics
        </h3>
        <ResponsiveContainer width="100%" height={300}>
          <ComposedChart data={combinedData}>
            <CartesianGrid strokeDasharray="3 3" stroke="#374151" />
            <XAxis 
              dataKey="timestamp" 
              stroke="#9CA3AF"
              style={{ fontSize: '12px' }}
            />
            <YAxis 
              stroke="#9CA3AF"
              style={{ fontSize: '12px' }}
            />
            <Tooltip
              contentStyle={{
                backgroundColor: '#1F2937',
                border: '1px solid #374151',
                borderRadius: '8px',
                color: '#F3F4F6'
              }}
            />
            <Legend />
            <Bar dataKey="lcp" name="LCP (ms)" fill="#10B981" />
            <Bar dataKey="fcp" name="FCP (ms)" fill="#06B6D4" />
            <Line
              type="monotone"
              dataKey="fid"
              name="FID (ms)"
              stroke="#F59E0B"
              strokeWidth={2}
            />
            <Line
              type="monotone"
              dataKey="ttfb"
              name="TTFB (ms)"
              stroke="#8B5CF6"
              strokeWidth={2}
            />
          </ComposedChart>
        </ResponsiveContainer>
      </div>
    );
  };

  const renderModerationChart = () => {
    if (!moderationData || moderationData.total.length === 0) {
      return <EmptyState message="No hay datos de moderación disponibles" />;
    }

    // Combinar datos para el gráfico
    const combinedData = moderationData.total.map((item, index) => ({
      timestamp: item.label || item.timestamp,
      total: item.value,
      pending: moderationData.pending[index]?.value || 0,
      underReview: moderationData.underReview[index]?.value || 0,
      resolved: moderationData.resolved[index]?.value || 0,
      dismissed: moderationData.dismissed[index]?.value || 0
    }));

    return (
      <div className="bg-white dark:bg-gray-800 p-6 rounded-xl shadow-lg border border-gray-200 dark:border-gray-700">
        <h3 className="text-lg font-semibold text-gray-900 dark:text-white mb-4">
          🛡️ Actividad de Moderación
        </h3>
        <ResponsiveContainer width="100%" height={300}>
          <BarChart data={combinedData}>
            <CartesianGrid strokeDasharray="3 3" stroke="#374151" />
            <XAxis 
              dataKey="timestamp" 
              stroke="#9CA3AF"
              style={{ fontSize: '12px' }}
            />
            <YAxis 
              stroke="#9CA3AF"
              style={{ fontSize: '12px' }}
            />
            <Tooltip
              contentStyle={{
                backgroundColor: '#1F2937',
                border: '1px solid #374151',
                borderRadius: '8px',
                color: '#F3F4F6'
              }}
            />
            <Legend />
            <Bar dataKey="pending" name="Pendientes" stackId="a" fill="#F59E0B" />
            <Bar dataKey="underReview" name="En Revisión" stackId="a" fill="#3B82F6" />
            <Bar dataKey="resolved" name="Resueltos" stackId="a" fill="#10B981" />
            <Bar dataKey="dismissed" name="Descartados" stackId="a" fill="#6B7280" />
          </BarChart>
        </ResponsiveContainer>
      </div>
    );
  };

  // =====================================================
  // RENDER
  // =====================================================

  if (loading) {
    return (
      <div className="flex items-center justify-center p-12">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600"></div>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Header con selector de rango */}
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-2xl font-bold text-gray-900 dark:text-white">
            📊 Gráficos Históricos
          </h2>
          <p className="text-sm text-gray-600 dark:text-gray-400 mt-1">
            Tendencias y análisis temporal de métricas
          </p>
        </div>
        <div className="flex items-center space-x-2">
          <span className="text-sm text-gray-600 dark:text-gray-400">Rango:</span>
          <select
            value={selectedRange}
            onChange={(e) => setSelectedRange(Number(e.target.value))}
            className="px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-lg text-sm bg-white dark:bg-gray-800 text-gray-900 dark:text-white"
            aria-label="Seleccionar rango de tiempo"
          >
            <option value={1}>Última hora</option>
            <option value={6}>Últimas 6 horas</option>
            <option value={12}>Últimas 12 horas</option>
            <option value={24}>Últimas 24 horas</option>
            <option value={48}>Últimas 48 horas</option>
            <option value={168}>Última semana</option>
          </select>
        </div>
      </div>

      {/* Grid de gráficos */}
      <div className="grid grid-cols-1 gap-6">
        {renderPerformanceChart()}
        {renderErrorChart()}
        {renderWebVitalsChart()}
        {renderModerationChart()}
      </div>
    </div>
  );
};

