import React, { useState, useRef, useEffect } from 'react';
import { cn } from '@/shared/lib/cn';

interface LazyImageLoaderProps {
  src: string;
  alt: string;
  className?: string;
  placeholder?: string;
  webpSrc?: string;
  avifSrc?: string;
  loading?: 'lazy' | 'eager';
  onLoad?: () => void;
  onError?: () => void;
}

export const LazyImageLoader: React.FC<LazyImageLoaderProps> = ({
  src,
  alt,
  className,
  placeholder = 'data:image/svg+xml;base64,PHN2ZyB3aWR0aD0iMzIwIiBoZWlnaHQ9IjMyMCIgeG1sbnM9Imh0dHA6Ly93d3cudzMub3JnLzIwMDAvc3ZnIj48cmVjdCB3aWR0aD0iMTAwJSIgaGVpZ2h0PSIxMDAlIiBmaWxsPSIjZGRkIi8+PC9zdmc+',
  webpSrc,
  avifSrc,
  loading = 'lazy',
  onLoad,
  onError
}) => {
  const [isLoaded, setIsLoaded] = useState(false);
  const [hasError, setHasError] = useState(false);
  const [currentSrc, setCurrentSrc] = useState(placeholder);
  const imgRef = useRef<HTMLImageElement>(null);
  const observerRef = useRef<IntersectionObserver | null>(null);

  // Detectar soporte para formatos modernos
  const supportsWebP = useRef<boolean | null>(null);
  const supportsAVIF = useRef<boolean | null>(null);

  useEffect(() => {
    // Detectar soporte WebP
    if (supportsWebP.current === null) {
      const webpTest = new Image();
      webpTest.onload = webpTest.onerror = () => {
        supportsWebP.current = webpTest.height === 2;
      };
      webpTest.src = 'data:image/webp;base64,UklGRjoAAABXRUJQVlA4IC4AAACyAgCdASoCAAIALmk0mk0iIiIiIgBoSygABc6WWgAA/veff/0PP8bA//LwYAAA';
    }

    // Detectar soporte AVIF
    if (supportsAVIF.current === null) {
      const avifTest = new Image();
      avifTest.onload = avifTest.onerror = () => {
        supportsAVIF.current = avifTest.height === 2;
      };
      avifTest.src = 'data:image/avif;base64,';
    }
  }, []);

  useEffect(() => {
    if (!imgRef.current) return;

    // Intersection Observer para lazy loading
    if (loading === 'lazy') {
      observerRef.current = new IntersectionObserver(
        (entries) => {
          entries.forEach((entry) => {
            if (entry.isIntersecting) {
              loadImage();
              observerRef.current?.disconnect();
            }
          });
        },
        {
          rootMargin: '50px' // Cargar 50px antes de ser visible
        }
      );

      observerRef.current.observe(imgRef.current as Element);
    } else {
      loadImage();
    }

    return () => {
      observerRef.current?.disconnect();
    };
  }, [src, webpSrc, avifSrc]);

  const loadImage = () => {
    // Seleccionar la mejor fuente disponible
    let selectedSrc = src;

    if (supportsAVIF.current && avifSrc) {
      selectedSrc = avifSrc;
    } else if (supportsWebP.current && webpSrc) {
      selectedSrc = webpSrc;
    }

    const img = new Image();

    img.onload = () => {
      setCurrentSrc(selectedSrc);
      setIsLoaded(true);
      setHasError(false);
      onLoad?.();
    };

    img.onerror = () => {
      // Fallback a formato original si falla
      if (selectedSrc !== src) {
        const fallbackImg = new Image();
        fallbackImg.onload = () => {
          setCurrentSrc(src);
          setIsLoaded(true);
          setHasError(false);
          onLoad?.();
        };
        fallbackImg.onerror = () => {
          setHasError(true);
          onError?.();
        };
        fallbackImg.src = src;
      } else {
        setHasError(true);
        onError?.();
      }
    };

    img.src = selectedSrc;
  };

  return (
    <div className="relative overflow-hidden">
      <img
        ref={imgRef}
        src={currentSrc}
        alt={alt}
        className={cn(
          'img-android transition-opacity duration-300',
          isLoaded ? 'opacity-100' : 'opacity-0',
          hasError && 'opacity-50',
          className
        )}
        loading={loading}
        decoding="async"
      />

      {/* Loading placeholder */}
      {!isLoaded && !hasError && (
        <div className="absolute inset-0 bg-gray-200 animate-pulse flex items-center justify-center">
          <div className="w-8 h-8 border-2 border-gray-300 border-t-blue-500 rounded-full animate-spin"></div>
        </div>
      )}

      {/* Error state */}
      {hasError && (
        <div className="absolute inset-0 bg-gray-100 flex items-center justify-center">
          <div className="text-gray-400 text-center">
            <svg className="w-8 h-8 mx-auto mb-2" fill="currentColor" viewBox="0 0 20 20">
              <path fillRule="evenodd" d="M4 3a2 2 0 00-2 2v10a2 2 0 002 2h12a2 2 0 002-2V5a2 2 0 00-2-2H4zm12 12H4l4-8 3 6 2-4 3 6z" clipRule="evenodd" />
            </svg>
            <span className="text-xs">Error al cargar</span>
          </div>
        </div>
      )}
    </div>
  );
};

export default LazyImageLoader;

import React from 'react';
import { motion } from 'framer-motion';
import { AnimationContext } from '@/components/animations/AnimationProvider';
import { UnifiedButton } from '@/components/ui/UnifiedButton';
import { UnifiedCard } from '@/components/ui/UnifiedCard';
import { Settings, Zap, Eye, Sparkles, Palette, Film } from 'lucide-react';
import { useBgMode } from '@/hooks/useBgMode';

interface AnimationSettingsProps {
  isOpen: boolean;
  onClose: () => void;
}

export const AnimationSettings: React.FC<AnimationSettingsProps> = ({ isOpen, onClose }) => {
  // CRÍTICO: Los hooks deben llamarse siempre, no condicionalmente
  // Usar useContext directamente y manejar el caso undefined después
  const context = React.useContext(AnimationContext);
  
  // Si no hay provider, mostrar mensaje o retornar null
  if (!context) {
    if (!isOpen) return null;
    return (
      <div className="fixed inset-0 bg-black/50 backdrop-blur-sm z-50 flex items-center justify-center p-4">
        <div className="bg-white/10 backdrop-blur-md border border-white/20 rounded-lg p-6 text-white">
          <p>AnimationProvider no está disponible</p>
          <button onClick={onClose} className="mt-4 px-4 py-2 bg-white/20 rounded">Cerrar</button>
        </div>
      </div>
    );
  }
  
  const { config, updateConfig } = context;
  const { mode, setMode, reducedMotion, toggleReducedMotion } = useBgMode();

  const overlayVariants = {
    hidden: { opacity: 0 },
    visible: { opacity: 1 }
  };

  const panelVariants = {
    hidden: { opacity: 0, scale: 0.8, y: 50 },
    visible: { 
      opacity: 1, 
      scale: 1, 
      y: 0,
      transition: { type: "spring", stiffness: 300, damping: 25 }
    }
  };

  if (!isOpen) return null;

  return (
    <motion.div
      variants={overlayVariants}
      initial="hidden"
      animate="visible"
      exit="hidden"
      className="fixed inset-0 bg-black/50 backdrop-blur-sm z-50 flex items-center justify-center p-4"
      onClick={onClose}
    >
      <motion.div
        variants={panelVariants}
        onClick={(e) => e.stopPropagation()}
        className="w-full max-w-md"
      >
        <UnifiedCard className="p-6 bg-white/10 backdrop-blur-md border border-white/20">
          <div className="flex items-center gap-3 mb-6">
            <Settings className="w-6 h-6 text-purple-400" />
            <h2 className="text-xl font-bold text-white">Configuración de Animaciones</h2>
          </div>

          <div className="space-y-6">
            {/* Reduced Motion Toggle */}
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-3">
                <Eye className="w-5 h-5 text-blue-400" />
                <div>
                  <p className="text-white font-medium">Movimiento Reducido</p>
                  <p className="text-white/60 text-sm">Para accesibilidad</p>
                </div>
              </div>
              <motion.button
                whileTap={{ scale: 0.95 }}
                onClick={() => updateConfig({ reducedMotion: !config.reducedMotion })}
                className={`relative w-12 h-6 rounded-full transition-colors ${
                  config.reducedMotion ? 'bg-purple-600' : 'bg-gray-600'
                }`}
              >
                <motion.div
                  animate={{ x: config.reducedMotion ? 24 : 0 }}
                  className="absolute top-0.5 left-0.5 w-5 h-5 bg-white rounded-full shadow-md"
                />
              </motion.button>
            </div>

            {/* Animation Speed */}
            <div>
              <div className="flex items-center gap-3 mb-3">
                <Zap className="w-5 h-5 text-yellow-400" />
                <p className="text-white font-medium">Velocidad de Animación</p>
              </div>
              <div className="grid grid-cols-3 gap-2">
                {(['slow', 'normal', 'fast'] as const).map((speed) => (
                  <UnifiedButton
                    key={speed}
                    variant={config.animationSpeed === speed ? 'love' : 'default'}
                    size="sm"
                    onClick={() => updateConfig({ animationSpeed: speed })}
                    className="capitalize"
                  >
                    {speed === 'slow' ? 'Lenta' : speed === 'normal' ? 'Normal' : 'Rápida'}
                  </UnifiedButton>
                ))}
              </div>
            </div>

            {/* Particles Toggle */}
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-3">
                <Sparkles className="w-5 h-5 text-pink-400" />
                <div>
                  <p className="text-white font-medium">Partículas Flotantes</p>
                  <p className="text-white/60 text-sm">Efectos de fondo</p>
                </div>
              </div>
              <motion.button
                whileTap={{ scale: 0.95 }}
                onClick={() => updateConfig({ enableParticles: !config.enableParticles })}
                className={`relative w-12 h-6 rounded-full transition-colors ${
                  config.enableParticles ? 'bg-purple-600' : 'bg-gray-600'
                }`}
              >
                <motion.div
                  animate={{ x: config.enableParticles ? 24 : 0 }}
                  className="absolute top-0.5 left-0.5 w-5 h-5 bg-white rounded-full shadow-md"
                />
              </motion.button>
            </div>

            {/* Background Animations Toggle */}
            <div className="flex items-center justify-between">
