                  className="capitalize"
                >
                  Fijo
                </UnifiedButton>
                <UnifiedButton
                  variant={mode === 'particles' ? 'love' : 'default'}
                  size="sm"
                  onClick={() => setMode('particles')}
                  className="capitalize"
                >
                  Partículas
                </UnifiedButton>
                <UnifiedButton
                  variant={mode === 'video' ? 'love' : 'default'}
                  size="sm"
                  onClick={() => setMode('video')}
                  className="capitalize"
                >
                  Vídeo
                </UnifiedButton>
              </div>
            </div>

            {/* Reduced Motion from useBgMode */}
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-3">
                <Eye className="w-5 h-5 text-blue-400" />
                <div>
                  <p className="text-white font-medium">Movimiento Reducido</p>
                  <p className="text-white/60 text-sm">Desde useBgMode</p>
                </div>
              </div>
              <motion.button
                whileTap={{ scale: 0.95 }}
                onClick={toggleReducedMotion}
                className={`relative w-12 h-6 rounded-full transition-colors ${
                  reducedMotion ? 'bg-purple-600' : 'bg-gray-600'
                }`}
              >
                <motion.div
                  animate={{ x: reducedMotion ? 24 : 0 }}
                  className="absolute top-0.5 left-0.5 w-5 h-5 bg-white rounded-full shadow-md"
                />
              </motion.button>
            </div>

            {/* Animation Preview */}
            <div className="border-t border-white/20 pt-4">
              <p className="text-white font-medium mb-3">Vista Previa</p>
              <div className="flex justify-center">
                <motion.div
                  animate={{ 
                    scale: [1, 1.2, 1],
                    rotate: [0, 180, 360]
                  }}
                  transition={{ 
                    duration: config.reducedMotion ? 0.01 : 2,
                    repeat: Infinity,
                    ease: "easeInOut"
                  }}
                  className="w-12 h-12 bg-gradient-to-r from-purple-500 to-pink-500 rounded-full"
                />
              </div>
            </div>
          </div>

          <div className="flex gap-3 mt-6">
            <UnifiedButton
              variant="default"
              onClick={onClose}
