            <UnifiedButton
              variant="love"
              onClick={() => {
                updateConfig({
                  reducedMotion: false,
                  animationSpeed: 'normal',
                  enableParticles: true,
                  enableBackgroundAnimations: true
                });
              }}
              className="flex-1"
            >
              Restablecer
            </UnifiedButton>
          </div>
        </UnifiedCard>
      </motion.div>
    </motion.div>
