import React, { createContext } from 'react';
import { motion, AnimatePresence, Variants } from 'framer-motion';
import { Heart, MessageCircle, Trophy, AlertCircle, CheckCircle, X, Mail, Bell, UserPlus } from 'lucide-react';

// Notification types - Extended for v3.1
export type NotificationType = 'match' | 'like' | 'message' | 'achievement' | 'success' | 'error' | 'warning' | 'info' | 'email' | 'request' | 'confirmation' | 'alert';

interface Notification {
  id: string;
  type: NotificationType;
  title: string;
  message: string;
  duration?: number;
  action?: {
    label: string;
    onClick: () => void;
  };
  data?: any;
}

// Notification context
interface NotificationContextType {
  notifications: Notification[];
  addNotification: (notification: Omit<Notification, 'id'>) => void;
  removeNotification: (id: string) => void;
  clearAll: () => void;
}

// CRÍTICO: Asegurar createContext disponible antes de usar
const safeCreateContext = <T,>(defaultValue: T | undefined): React.Context<T | undefined> => {
  const debugLog = (event: string, data?: any) => {
    if (typeof window !== 'undefined' && (window as any).__LOADING_DEBUG__) {
      (window as any).__LOADING_DEBUG__.log(event, data);
    }
  };
  
  if (typeof window !== 'undefined' && (window as any).React?.createContext) {
    debugLog('SAFE_CREATE_CONTEXT_GLOBAL', { provider: 'NotificationSystem', hasGlobal: true });
    return (window as any).React.createContext(defaultValue);
  }
  
  debugLog('SAFE_CREATE_CONTEXT_FALLBACK', { provider: 'NotificationSystem', hasGlobal: false, hasLocal: !!createContext });
  return createContext<T | undefined>(defaultValue);
};

const NotificationContext = safeCreateContext<NotificationContextType>(undefined);

// Notification provider
export const NotificationProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [notifications, setNotifications] = React.useState<Notification[]>([]);

  const addNotification = React.useCallback((notification: Omit<Notification, 'id'>) => {
    const id = Date.now().toString();
    const newNotification = { ...notification, id };
    
    setNotifications(prev => [...prev, newNotification]);

    // Auto remove after duration
    if (notification.duration !== 0) {
      setTimeout(() => {
        removeNotification(id);
      }, notification.duration || 5000);
    }
  }, []);

  const removeNotification = React.useCallback((id: string) => {
    setNotifications(prev => prev.filter(n => n.id !== id));
  }, []);

  const clearAll = React.useCallback(() => {
    setNotifications([]);
  }, []);

  return (
    <NotificationContext.Provider value={{
      notifications,
      addNotification,
      removeNotification,
      clearAll
    }}>
      {children}
      <NotificationContainer />
    </NotificationContext.Provider>
  );
};

// Hook to use notifications
export const useNotifications = () => {
  const context = React.useContext(NotificationContext);
  if (!context) {
    throw new Error('useNotifications must be used within NotificationProvider');
  }
  return context;
};

// Individual notification component
const NotificationItem: React.FC<{ notification: Notification }> = ({ notification }) => {
  const { removeNotification } = useNotifications();
  
  const getIcon = () => {
    switch (notification.type) {
      case 'match': return <Heart className="w-5 h-5 text-red-400" fill="currentColor" />;
      case 'like': return <Heart className="w-5 h-5 text-pink-400" />;
      case 'message': return <MessageCircle className="w-5 h-5 text-blue-400" />;
      case 'achievement': return <Trophy className="w-5 h-5 text-yellow-400" />;
      case 'success': return <CheckCircle className="w-5 h-5 text-green-400" />;
      case 'error': return <AlertCircle className="w-5 h-5 text-red-400" />;
      case 'warning': return <AlertCircle className="w-5 h-5 text-yellow-400" />;
      case 'email': return <Mail className="w-5 h-5 text-blue-500" />;
      case 'request': return <UserPlus className="w-5 h-5 text-purple-500" />;
      case 'confirmation': return <CheckCircle className="w-5 h-5 text-green-500" />;
      case 'alert': return <Bell className="w-5 h-5 text-red-500" />;
      default: return <AlertCircle className="w-5 h-5 text-blue-400" />;
    }
  };

  const getColors = () => {
    switch (notification.type) {
      case 'match': return 'from-red-500 to-pink-500';
      case 'like': return 'from-pink-500 to-rose-500';
      case 'message': return 'from-blue-500 to-cyan-500';
      case 'achievement': return 'from-yellow-500 to-orange-500';
      case 'success': return 'from-green-500 to-emerald-500';
      case 'error': return 'from-red-500 to-red-600';
      case 'warning': return 'from-yellow-500 to-yellow-600';
      case 'email': return 'from-blue-500 to-indigo-500';
      case 'request': return 'from-purple-500 to-violet-500';
      case 'confirmation': return 'from-green-500 to-teal-500';
      case 'alert': return 'from-red-500 to-orange-500';
      default: return 'from-blue-500 to-blue-600';
    }
  };

  const itemVariants: Variants = {
    initial: { opacity: 0, x: 300, scale: 0.8 },
    animate: { 
      opacity: 1, 
      x: 0, 
      scale: 1,
      transition: { 
        duration: 0.3
      }
    },
    exit: { 
      opacity: 0, 
      x: 300, 
      scale: 0.8,
      transition: { duration: 0.2 }
    }
  };

  return (
    <motion.div
      variants={itemVariants}
      initial="initial"
      animate="animate"
      exit="exit"
      layout
      className={`relative overflow-hidden rounded-lg shadow-lg backdrop-blur-sm bg-white/10 border border-white/20 p-4 mb-3 max-w-sm`}
    >
      {/* Animated background gradient */}
      <motion.div
        className={`absolute inset-0 bg-gradient-to-r ${getColors()} opacity-20`}
        animate={{ 
          background: [
            `linear-gradient(45deg, ${getColors()})`,
            `linear-gradient(135deg, ${getColors()})`,
            `linear-gradient(225deg, ${getColors()})`,
            `linear-gradient(315deg, ${getColors()})`,
            `linear-gradient(45deg, ${getColors()})`
          ]
        }}
        transition={{ duration: 3, repeat: Infinity }}
      />
      
      <div className="relative flex items-start gap-3">
        <motion.div
          animate={{ rotate: [0, 10, -10, 0] }}
          transition={{ duration: 0.5, delay: 0.2 }}
        >
          {getIcon()}
        </motion.div>
        
        <div className="flex-1 min-w-0">
          <h4 className="text-sm font-semibold text-white truncate">
            {notification.title}
          </h4>
          <p className="text-xs text-white/80 mt-1">
            {notification.message}
          </p>
          
          {notification.action && (
            <motion.button
              whileHover={{ scale: 1.05 }}
              whileTap={{ scale: 0.95 }}
              onClick={notification.action.onClick}
              className="mt-2 px-3 py-1 bg-white/20 hover:bg-white/30 rounded text-xs text-white font-medium transition-colors"
            >
              {notification.action.label}
            </motion.button>
          )}
        </div>
        
        <motion.button
          whileHover={{ scale: 1.1 }}
          whileTap={{ scale: 0.9 }}
          onClick={() => removeNotification(notification.id)}
          className="text-white/60 hover:text-white transition-colors"
        >
          <X className="w-4 h-4" />
        </motion.button>
      </div>
    </motion.div>
  );
};

// Notification container
const NotificationContainer: React.FC = () => {
  // CRÍTICO: Los hooks deben llamarse siempre, no condicionalmente
  // Usar useContext directamente y manejar el caso undefined después
  const context = React.useContext(NotificationContext);
  
  // Si no hay provider, retornar null silenciosamente
  if (!context) {
    return null;
  }
  
  const { notifications } = context;

  return (
    <div className="fixed top-4 right-4 z-50 pointer-events-none">
      <AnimatePresence mode="popLayout">
        {notifications.map((notification) => (
          <div key={notification.id} className="pointer-events-auto">
            <NotificationItem notification={notification} />
          </div>
        ))}
      </AnimatePresence>
    </div>
  );
};

// Special effect notifications
export const MatchNotification: React.FC<{ user: { id: string; name: string } }> = ({ user }) => {
  const { addNotification } = useNotifications();
  
  React.useEffect(() => {
    addNotification({
      type: 'match',
      title: '¡Es un Match! 💕',
      message: `¡Tú y ${user.name} se han gustado mutuamente!`,
      duration: 8000,
      action: {
        label: 'Enviar mensaje',
        onClick: () => {
          // Navigate to chat
          window.location.href = `/chat?user=${user.id || ''}`;
        }
      },
      data: user
    });
  }, [user, addNotification]);

  return (
    <motion.div
      initial={{ scale: 0 }}
      animate={{ scale: [0, 1.2, 1] }}
      className="fixed inset-0 flex items-center justify-center z-50 pointer-events-none"
    >
      <motion.div
        animate={{ 
          rotate: [0, 360],
          scale: [1, 1.1, 1]
        }}
        transition={{ 
          rotate: { duration: 2, repeat: Infinity, ease: "linear" },
          scale: { duration: 1, repeat: Infinity, repeatType: "reverse" }
        }}
        className="text-6xl"
      >
        💕
      </motion.div>
    </motion.div>
  );
};

// Achievement notification with confetti
export const AchievementNotification: React.FC<{ achievement: any }> = ({ achievement }) => {
  const { addNotification } = useNotifications();
  
  React.useEffect(() => {
    addNotification({
      type: 'achievement',
      title: '¡Logro Desbloqueado! 🏆',
      message: achievement.description,
      duration: 6000,
      data: achievement
    });
  }, [achievement, addNotification]);

  return (
    <motion.div
      initial={{ y: -100, opacity: 0 }}
      animate={{ y: 0, opacity: 1 }}
      exit={{ y: -100, opacity: 0 }}
      className="fixed top-20 left-1/2 transform -translate-x-1/2 z-50"
    >
      <motion.div
        animate={{ 
          boxShadow: [
            '0 0 20px rgba(255, 215, 0, 0.3)',
            '0 0 40px rgba(255, 215, 0, 0.6)',
            '0 0 20px rgba(255, 215, 0, 0.3)'
          ]
        }}
        transition={{ duration: 2, repeat: Infinity }}
        className="bg-gradient-to-r from-yellow-400 to-orange-500 text-white px-6 py-3 rounded-full font-bold shadow-lg"
      >
        <div className="flex items-center gap-2">
          <Trophy className="w-5 h-5" />
          <span>{achievement.title}</span>
        </div>
      </motion.div>
    </motion.div>
  );
};

// Floating hearts for likes
export const FloatingHearts: React.FC<{ count?: number }> = ({ count = 5 }) => {
  const hearts = Array.from({ length: count }, (_, i) => (
    <motion.div
      key={i}
      initial={{ 
        opacity: 0, 
        scale: 0, 
        x: Math.random() * 100 - 50,
        y: 0 
      }}
      animate={{ 
        opacity: [0, 1, 0], 
        scale: [0, 1, 0.8], 
        y: -200,
        x: Math.random() * 200 - 100
      }}
      transition={{ 
        duration: 3, 
        delay: i * 0.2,
        ease: "easeOut"
      }}
      className="absolute text-2xl pointer-events-none"
      style={{ 
        left: '50%', 
        bottom: '50%',
        transform: 'translateX(-50%)'
      }}
    >
      ❤️
    </motion.div>
  ));

  return (
    <div className="fixed inset-0 pointer-events-none z-40">
      {hearts}
    </div>
  );
};

// Hook for easy notification usage
export const useNotificationHelpers = () => {
  const { addNotification } = useNotifications();
  
  return {
    showMatch: (user: { id: string; name: string }) => {
      addNotification({
        type: 'match',
        title: '¡Es un Match! 💕',
        message: `¡Tú y ${user.name} se han gustado mutuamente!`,
        duration: 8000,
        action: {
          label: 'Enviar mensaje',
          onClick: () => window.location.href = `/chat?user=${user.id || ''}`
        }
      });
    },
    
    showLike: (user: { id: string; name: string }) => {
      addNotification({
        type: 'like',
        title: '¡Nuevo Like! 💖',
        message: `A ${user.name} le gustas`,
        duration: 4000
      });
    },
    
    showMessage: (sender: { id: string; name: string }, _message: string) => {
      addNotification({
        type: 'message',
        title: 'Nuevo mensaje 💬',
        message: `${sender.name} te ha enviado un mensaje`,
        duration: 6000,
        action: {
          label: 'Ver mensaje',
          onClick: () => window.location.href = `/chat?user=${sender.id}`
        }
      });
    },
    
    showAchievement: (achievement: any) => {
      addNotification({
        type: 'achievement',
        title: '¡Logro Desbloqueado! 🏆',
        message: achievement.description,
        duration: 6000
      });
    },
    
    showSuccess: (message: string) => {
      addNotification({
        type: 'success',
        title: '¡Éxito!',
        message,
        duration: 3000
      });
    },
    
    showError: (message: string) => {
      addNotification({
        type: 'error',
        title: 'Error',
        message,
        duration: 5000
      });
    },
    
    showWarning: (message: string) => {
      addNotification({
        type: 'warning',
        title: 'Atención',
        message,
        duration: 4000
      });
    },
    
    showInfo: (message: string) => {
      addNotification({
        type: 'info',
        title: 'Información',
        message,
        duration: 4000
      });
    },

    // New v3.1 notification helpers
    showEmailNotification: (title: string, message: string, actionUrl?: string) => {
      addNotification({
        type: 'email',
        title,
        message,
        duration: 6000,
        action: actionUrl ? {
          label: 'Ver detalles',
          onClick: () => window.location.href = actionUrl
        } : undefined
      });
    },

    showNewRequest: (senderName: string, requestId: string) => {
      addNotification({
        type: 'request',
        title: 'Nueva Solicitud',
        message: `${senderName} te ha enviado una solicitud de conexión`,
        duration: 8000,
        action: {
          label: 'Ver solicitud',
          onClick: () => window.location.href = `/requests?id=${requestId}`
        }
      });
    },

    showConfirmation: (title: string, message: string) => {
      addNotification({
        type: 'confirmation',
        title,
        message,
        duration: 5000
      });
    },

    showAlert: (title: string, message: string, actionUrl?: string) => {
      addNotification({
        type: 'alert',
        title,
        message,
        duration: 0, // Persistent until dismissed
        action: actionUrl ? {
          label: 'Resolver',
          onClick: () => window.location.href = actionUrl
        } : undefined
      });
    }
  };
};

/**
 * =====================================================
 * VOICE RECORDER
 * =====================================================
 * Grabador de mensajes de voz para el chat
 * Features: Grabar, pausar, vista de onda, enviar
 * Fecha: 19 Nov 2025
 * Versión: v3.6.5
 * =====================================================
 */

import React, { useState, useRef, useEffect } from 'react';
import { Mic, Square, Play, Pause, Trash2, Send } from 'lucide-react';
import { motion } from 'framer-motion';
import { Button } from '@/shared/ui/Button';
import { logger } from '@/lib/logger';

interface VoiceRecorderProps {
  onAudioReady: (blob: Blob, duration: number) => void;
  onCancel?: () => void;
  maxDuration?: number; // en segundos
  className?: string;
}

export const VoiceRecorder: React.FC<VoiceRecorderProps> = ({
  onAudioReady,
  onCancel,
  maxDuration = 120, // 2 minutos por defecto
  className = ''
}) => {
  const [isRecording, setIsRecording] = useState(false);
  const [isPaused, setIsPaused] = useState(false);
  const [duration, setDuration] = useState(0);
  const [audioBlob, setAudioBlob] = useState<Blob | null>(null);
  const [audioUrl, setAudioUrl] = useState<string>('');
  const [error, setError] = useState<string>('');
  const [isPlaying, setIsPlaying] = useState(false);

  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const audioRef = useRef<HTMLAudioElement | null>(null);
  const chunksRef = useRef<Blob[]>([]);
  const timerRef = useRef<NodeJS.Timeout | null>(null);

  /**
   * Formatear duración
   */
  const formatDuration = (seconds: number): string => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  /**
   * Iniciar grabación
   */
  const startRecording = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      const mediaRecorder = new MediaRecorder(stream);

      mediaRecorder.ondataavailable = (e) => {
        if (e.data.size > 0) {
          chunksRef.current.push(e.data);
        }
      };

      mediaRecorder.onstop = () => {
        const blob = new Blob(chunksRef.current, { type: 'audio/webm' });
        setAudioBlob(blob);
        setAudioUrl(URL.createObjectURL(blob));

        // Detener tracks
        stream.getTracks().forEach(track => track.stop());
      };

      mediaRecorderRef.current = mediaRecorder;
      mediaRecorder.start();
      setIsRecording(true);
      setError('');

      // Iniciar timer
      timerRef.current = setInterval(() => {
        setDuration(prev => {
          if (prev >= maxDuration) {
            stopRecording();
            return prev;
          }
          return prev + 1;
        });
      }, 1000);

    } catch (err) {
      logger.error('[VoiceRecorder] Error starting recording:', { error: err });
      setError('No se pudo acceder al micrófono. Verifica los permisos.');
    }
  };

  /**
   * Pausar/reanudar grabación
   */
  const togglePause = () => {
    if (!mediaRecorderRef.current) return;

    if (isPaused) {
      mediaRecorderRef.current.resume();
      setIsPaused(false);
    } else {
      mediaRecorderRef.current.pause();
      setIsPaused(true);
    }
  };

  /**
   * Detener grabación
   */
  const stopRecording = () => {
    if (mediaRecorderRef.current && mediaRecorderRef.current.state !== 'inactive') {
      mediaRecorderRef.current.stop();
    }

    if (timerRef.current) {
      clearInterval(timerRef.current);
      timerRef.current = null;
    }

    setIsRecording(false);
    setIsPaused(false);
  };

  /**
   * Cancelar y limpiar
   */
  const handleCancel = () => {
    stopRecording();
    setDuration(0);
    setAudioBlob(null);
    setAudioUrl('');
    chunksRef.current = [];
    onCancel?.();
  };

  /**
   * Enviar audio
   */
  const handleSend = () => {
    if (audioBlob) {
      onAudioReady(audioBlob, duration);
      handleCancel();
    }
  };

  /**
   * Toggle play/pause de audio
   */
  const togglePlayback = () => {
    if (!audioRef.current) return;

    if (isPlaying) {
      audioRef.current.pause();
      setIsPlaying(false);
    } else {
      audioRef.current.play();
      setIsPlaying(true);
    }
  };

  /**
   * Cleanup al desmontar
   */
  useEffect(() => {
    return () => {
      if (timerRef.current) {
        clearInterval(timerRef.current);
      }
      if (audioUrl) {
        URL.revokeObjectURL(audioUrl);
      }
    };
  }, [audioUrl]);

  return (
    <motion.div
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      exit={{ opacity: 0, y: 20 }}
      className={`bg-white dark:bg-gray-900 rounded-xl shadow-xl border border-gray-200 dark:border-gray-700 p-4 ${className}`}
    >
      {/* Header */}
      <div className="flex items-center justify-between mb-4">
        <div className="flex items-center gap-2">
          <Mic className={`h-5 w-5 ${isRecording ? 'text-red-500 animate-pulse' : 'text-gray-400'}`} />
          <h3 className="text-lg font-semibold text-gray-900 dark:text-white">
            Mensaje de Voz
          </h3>
        </div>
        <div className="text-sm font-mono text-gray-600 dark:text-gray-400">
          {formatDuration(duration)} / {formatDuration(maxDuration)}
        </div>
      </div>

      {/* Error */}
      {error && (
        <div className="mb-4 p-3 bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800 rounded-lg">
          <p className="text-sm text-red-600 dark:text-red-400">{error}</p>
        </div>
      )}

      {/* Waveform Visualization (simulado) */}
      <div className="mb-4 h-20 bg-gray-100 dark:bg-gray-800 rounded-lg flex items-center justify-center gap-1 p-4">
        {isRecording ? (
          Array.from({ length: 30 }).map((_, i) => (
            <motion.div
              key={i}
              className="w-1 bg-purple-500 rounded-full"
              animate={{
                height: [
                  Math.random() * 40 + 10,
                  Math.random() * 60 + 10,
                  Math.random() * 40 + 10
                ]
              }}
              transition={{
                duration: 0.5,
                repeat: Infinity,
                delay: i * 0.05
              }}
            />
          ))
        ) : audioBlob ? (
          <div className="text-center">
            <p className="text-sm text-gray-600 dark:text-gray-400 mb-2">
              Grabación completada
            </p>
            <audio
              ref={audioRef}
              src={audioUrl}
              onEnded={() => setIsPlaying(false)}
              className="hidden"
            />
            <Button
              variant="outline"
              size="sm"
              onClick={togglePlayback}
            >
              {isPlaying ? (
                <>
                  <Pause className="h-4 w-4 mr-2" />
                  Pausar
                </>
              ) : (
                <>
                  <Play className="h-4 w-4 mr-2" />
                  Escuchar
                </>
              )}
            </Button>
          </div>
        ) : (
          <p className="text-sm text-gray-400">
            Presiona el botón de grabar para iniciar
          </p>
        )}
      </div>

      {/* Controls */}
      <div className="flex items-center justify-between gap-2">
        {!audioBlob ? (
          <>
            {/* Recording controls */}
            <div className="flex items-center gap-2">
              {!isRecording ? (
                <Button
                  onClick={startRecording}
                  className="bg-red-500 hover:bg-red-600"
                >
                  <Mic className="h-4 w-4 mr-2" />
                  Grabar
                </Button>
              ) : (
                <>
                  <Button
                    variant="outline"
                    onClick={togglePause}
                  >
                    {isPaused ? (
                      <>
                        <Play className="h-4 w-4 mr-2" />
                        Continuar
                      </>
                    ) : (
                      <>
                        <Pause className="h-4 w-4 mr-2" />
                        Pausar
                      </>
                    )}
                  </Button>
                  <Button
                    variant="outline"
                    onClick={stopRecording}
                  >
                    <Square className="h-4 w-4 mr-2" />
                    Detener
                  </Button>
                </>
              )}
            </div>
            <Button
              variant="outline"
              onClick={handleCancel}
            >
              Cancelar
            </Button>
          </>
        ) : (
          <>
            {/* Playback controls */}
            <Button
              variant="outline"
              onClick={handleCancel}
            >
              <Trash2 className="h-4 w-4 mr-2" />
              Eliminar
            </Button>
            <Button
              onClick={handleSend}
              className="bg-purple-500 hover:bg-purple-600"
            >
              <Send className="h-4 w-4 mr-2" />
              Enviar
            </Button>
          </>
        )}
      </div>

      {/* Info */}
      <p className="mt-3 text-xs text-gray-500 text-center">
        {isRecording
          ? isPaused
            ? 'Grabación pausada'
            : 'Grabando...'
          : audioBlob
          ? 'Escucha tu mensaje antes de enviar'
          : 'Máximo 2 minutos de grabación'}
      </p>
    </motion.div>
  );
};

export default VoiceRecorder;

/**
 * =====================================================
 * ANALYTICS DASHBOARD
 * =====================================================
 * Dashboard de analíticas y estadísticas del usuario
 * Features: Charts, métricas en tiempo real, comparaciones
 * Fecha: 19 Nov 2025
 * Versión: v3.6.5
 * =====================================================
 */

import React, { useState, useEffect } from 'react';
import { TrendingUp, Users, Heart, Eye, MessageCircle, Star, Award } from 'lucide-react';
import { motion } from 'framer-motion';
import { Card, CardContent, CardHeader, CardTitle } from '@/shared/ui/Card';

interface AnalyticsDashboardProps {
  userId: string;
  profileType: 'single' | 'couple';
}

interface Metrics {
  profileViews: {
    today: number;
    week: number;
    month: number;
    total: number;
    trend: number; // % cambio vs periodo anterior
  };
  likes: {
    received: number;
    sent: number;
    mutual: number;
    trend: number;
  };
  messages: {
    sent: number;
    received: number;
    conversations: number;
    avgResponseTime: number; // minutos
  };
  matches: {
    total: number;
    thisWeek: number;
    compatibility: number; // % promedio
  };
  engagement: {
    score: number; // 0-100
    activityLevel: 'low' | 'medium' | 'high';
    lastActive: Date;
  };
}

interface ChartData {
  label: string;
  value: number;
}

export const AnalyticsDashboard: React.FC<AnalyticsDashboardProps> = ({
  userId,
  profileType
}) => {
  const [metrics, setMetrics] = useState<Metrics>({
    profileViews: {
      today: 0,
      week: 0,
      month: 0,
      total: 0,
      trend: 0
    },
    likes: {
      received: 0,
      sent: 0,
      mutual: 0,
      trend: 0
    },
    messages: {
      sent: 0,
      received: 0,
      conversations: 0,
      avgResponseTime: 0
    },
    matches: {
      total: 0,
      thisWeek: 0,
      compatibility: 0
    },
    engagement: {
      score: 0,
      activityLevel: 'medium',
      lastActive: new Date()
    }
  });

  const [viewsChart, setViewsChart] = useState<ChartData[]>([]);
  const [timeRange, setTimeRange] = useState<'week' | 'month' | 'year'>('week');

  /**
   * Cargar métricas
   */
  useEffect(() => {
    loadMetrics();
  }, [userId, timeRange]);

  const loadMetrics = async () => {
    // TODO: En producción, obtener desde API
    // Simulación de datos
    const mockMetrics: Metrics = {
      profileViews: {
        today: Math.floor(Math.random() * 50) + 10,
        week: Math.floor(Math.random() * 200) + 50,
        month: Math.floor(Math.random() * 800) + 200,
        total: Math.floor(Math.random() * 5000) + 1000,
        trend: (Math.random() * 40) - 10 // -10% a +30%
      },
      likes: {
        received: Math.floor(Math.random() * 100) + 20,
        sent: Math.floor(Math.random() * 80) + 15,
        mutual: Math.floor(Math.random() * 30) + 5,
        trend: (Math.random() * 50) - 15
      },
      messages: {
        sent: Math.floor(Math.random() * 150) + 30,
        received: Math.floor(Math.random() * 180) + 40,
        conversations: Math.floor(Math.random() * 20) + 5,
        avgResponseTime: Math.floor(Math.random() * 60) + 5
      },
      matches: {
        total: Math.floor(Math.random() * 50) + 10,
        thisWeek: Math.floor(Math.random() * 10) + 1,
        compatibility: Math.floor(Math.random() * 30) + 60
      },
      engagement: {
        score: Math.floor(Math.random() * 40) + 50,
        activityLevel: ['low', 'medium', 'high'][Math.floor(Math.random() * 3)] as any,
        lastActive: new Date()
      }
    };

    setMetrics(mockMetrics);

    // Chart data
    const mockChart: ChartData[] = [];
    const days = timeRange === 'week' ? 7 : timeRange === 'month' ? 30 : 365;

    for (let i = days - 1; i >= 0; i--) {
      const date = new Date();
      date.setDate(date.getDate() - i);
      mockChart.push({
        label: date.toLocaleDateString('es-MX', { month: 'short', day: 'numeric' }),
        value: Math.floor(Math.random() * 100) + 10
      });
    }

    setViewsChart(mockChart);
  };

  /**
   * Formatear números
   */
  const formatNumber = (num: number): string => {
    if (num >= 1000000) return `${(num / 1000000).toFixed(1)}M`;
    if (num >= 1000) return `${(num / 1000).toFixed(1)}K`;
    return num.toString();
  };

  /**
   * Renderizar tendencia
   */
  const renderTrend = (trend: number) => {
    const isPositive = trend >= 0;
    return (
      <div className={`flex items-center gap-1 text-sm ${isPositive ? 'text-green-600' : 'text-red-600'}`}>
        <TrendingUp className={`h-4 w-4 ${!isPositive && 'rotate-180'}`} />
        <span>{Math.abs(trend).toFixed(1)}%</span>
      </div>
    );
  };

  /**
   * Renderizar gráfico de barras simple
   */
  const renderSimpleChart = (data: ChartData[]) => {
    const maxValue = Math.max(...data.map(d => d.value));
    const lastFew = data.slice(-7); // Últimos 7 días

    return (
      <div className="flex items-end gap-2 h-32">
        {lastFew.map((item, index) => (
          <div
            key={index}
            className="flex-1 flex flex-col items-center gap-1"
          >
            <motion.div
              initial={{ height: 0 }}
              animate={{ height: `${(item.value / maxValue) * 100}%` }}
              transition={{ delay: index * 0.1 }}
              className="w-full bg-gradient-to-t from-purple-500 to-pink-500 rounded-t-lg min-h-[20px]"
            />
            <span className="text-xs text-gray-500 dark:text-gray-400 rotate-45 origin-left">
              {item.label.split(' ')[0]}
            </span>
          </div>
        ))}
      </div>
    );
  };

  return (
    <div className="max-w-7xl mx-auto p-4 space-y-6">
      {/* Header */}
      <div>
        <h1 className="text-3xl font-bold text-gray-900 dark:text-white">
          Dashboard de Analíticas
        </h1>
        <p className="text-gray-600 dark:text-gray-400 mt-1">
          Monitorea el rendimiento de tu perfil {profileType === 'couple' ? 'de pareja' : 'individual'}
        </p>
      </div>

      {/* Time Range Selector */}
      <div className="flex gap-2">
        {(['week', 'month', 'year'] as const).map((range) => (
          <button
            key={range}
            onClick={() => setTimeRange(range)}
            className={`px-4 py-2 rounded-lg transition-colors ${
              timeRange === range
                ? 'bg-purple-500 text-white'
                : 'bg-gray-100 dark:bg-gray-800 text-gray-700 dark:text-gray-300 hover:bg-gray-200 dark:hover:bg-gray-700'
            }`}
          >
            {range === 'week' && 'Última Semana'}
            {range === 'month' && 'Último Mes'}
            {range === 'year' && 'Último Año'}
          </button>
        ))}
      </div>

      {/* Main Metrics Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
        {/* Profile Views */}
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0 }}
        >
          <Card>
            <CardHeader className="flex flex-row items-center justify-between pb-2">
              <CardTitle className="text-sm font-medium">Visitas al Perfil</CardTitle>
              <Eye className="h-4 w-4 text-purple-500" />
            </CardHeader>
            <CardContent>
              <div className="text-2xl font-bold">{formatNumber(metrics.profileViews.total)}</div>
              <p className="text-xs text-gray-500 mt-1">
                {metrics.profileViews.today} hoy • {metrics.profileViews.week} esta semana
              </p>
              <div className="mt-2">
                {renderTrend(metrics.profileViews.trend)}
              </div>
            </CardContent>
          </Card>
        </motion.div>

        {/* Likes */}
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.1 }}
        >
          <Card>
            <CardHeader className="flex flex-row items-center justify-between pb-2">
              <CardTitle className="text-sm font-medium">Likes</CardTitle>
              <Heart className="h-4 w-4 text-pink-500" />
            </CardHeader>
            <CardContent>
              <div className="text-2xl font-bold">{formatNumber(metrics.likes.received)}</div>
              <p className="text-xs text-gray-500 mt-1">
                {metrics.likes.mutual} mutuos • {metrics.likes.sent} enviados
              </p>
              <div className="mt-2">
                {renderTrend(metrics.likes.trend)}
              </div>
            </CardContent>
          </Card>
        </motion.div>

        {/* Messages */}
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.2 }}
        >
          <Card>
            <CardHeader className="flex flex-row items-center justify-between pb-2">
              <CardTitle className="text-sm font-medium">Mensajes</CardTitle>
              <MessageCircle className="h-4 w-4 text-blue-500" />
            </CardHeader>
            <CardContent>
              <div className="text-2xl font-bold">{formatNumber(metrics.messages.received)}</div>
              <p className="text-xs text-gray-500 mt-1">
                {metrics.messages.conversations} conversaciones activas
              </p>
              <p className="text-xs text-gray-500 mt-1">
                Responde en ~{metrics.messages.avgResponseTime} min
              </p>
            </CardContent>
          </Card>
        </motion.div>

        {/* Matches */}
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.3 }}
        >
          <Card>
            <CardHeader className="flex flex-row items-center justify-between pb-2">
              <CardTitle className="text-sm font-medium">Matches</CardTitle>
              <Users className="h-4 w-4 text-green-500" />
            </CardHeader>
            <CardContent>
              <div className="text-2xl font-bold">{formatNumber(metrics.matches.total)}</div>
              <p className="text-xs text-gray-500 mt-1">
                {metrics.matches.thisWeek} nuevos esta semana
              </p>
              <p className="text-xs text-purple-500 mt-1 font-medium">
                {metrics.matches.compatibility}% compatibilidad promedio
              </p>
            </CardContent>
          </Card>
        </motion.div>
      </div>

      {/* Chart Section */}
      <motion.div
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ delay: 0.4 }}
      >
        <Card>
          <CardHeader>
            <CardTitle>Visitas a tu Perfil</CardTitle>
          </CardHeader>
          <CardContent>
            {renderSimpleChart(viewsChart)}
          </CardContent>
        </Card>
      </motion.div>

      {/* Engagement & Stats */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* Engagement Score */}
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.5 }}
        >
          <Card>
            <CardHeader>
              <CardTitle className="flex items-center gap-2">
                <Star className="h-5 w-5 text-yellow-500" />
                Nivel de Engagement
              </CardTitle>
            </CardHeader>
            <CardContent>
              <div className="space-y-4">
                <div>
                  <div className="flex items-center justify-between mb-2">
                    <span className="text-sm font-medium">Score de Actividad</span>
                    <span className="text-2xl font-bold text-purple-500">
                      {metrics.engagement.score}/100
                    </span>
                  </div>
                  <div className="w-full bg-gray-200 dark:bg-gray-700 rounded-full h-3">
                    <motion.div
                      initial={{ width: 0 }}
                      animate={{ width: `${metrics.engagement.score}%` }}
                      transition={{ duration: 1, delay: 0.5 }}
                      className="bg-gradient-to-r from-purple-500 to-pink-500 h-3 rounded-full"
                    />
                  </div>
                </div>

                <div className="flex items-center justify-between py-2 border-t dark:border-gray-700">
                  <span className="text-sm text-gray-600 dark:text-gray-400">Nivel de Actividad</span>
                  <span className={`text-sm font-medium px-3 py-1 rounded-full ${
                    metrics.engagement.activityLevel === 'high'
                      ? 'bg-green-100 dark:bg-green-900/30 text-green-700 dark:text-green-400'
                      : metrics.engagement.activityLevel === 'medium'
                      ? 'bg-yellow-100 dark:bg-yellow-900/30 text-yellow-700 dark:text-yellow-400'
                      : 'bg-red-100 dark:bg-red-900/30 text-red-700 dark:text-red-400'
                  }`}>
                    {metrics.engagement.activityLevel === 'high' && 'Alto'}
                    {metrics.engagement.activityLevel === 'medium' && 'Medio'}
                    {metrics.engagement.activityLevel === 'low' && 'Bajo'}
                  </span>
                </div>

                <div className="flex items-center justify-between py-2 border-t dark:border-gray-700">
                  <span className="text-sm text-gray-600 dark:text-gray-400">Última actividad</span>
                  <span className="text-sm font-medium">Hace {Math.floor((Date.now() - metrics.engagement.lastActive.getTime()) / 60000)} min</span>
                </div>
              </div>
            </CardContent>
          </Card>
        </motion.div>

        {/* Achievements */}
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.6 }}
        >
          <Card>
            <CardHeader>
              <CardTitle className="flex items-center gap-2">
                <Award className="h-5 w-5 text-yellow-500" />
                Logros Recientes
              </CardTitle>
            </CardHeader>
            <CardContent>
              <div className="space-y-3">
                {[
                  { icon: '🔥', title: 'Racha de 7 días', desc: 'Activo todos los días esta semana' },
                  { icon: '💬', title: 'Conversador', desc: 'Iniciaste 10+ conversaciones' },
                  { icon: '⭐', title: 'Popular', desc: 'Recibiste 50+ visitas este mes' },
                  { icon: '💖', title: 'Encantador', desc: '25+ likes recibidos' }
                ].map((achievement, index) => (
                  <div
                    key={index}
                    className="flex items-center gap-3 p-3 bg-gray-50 dark:bg-gray-800 rounded-lg"
                  >
                    <div className="text-2xl">{achievement.icon}</div>
                    <div className="flex-1">
                      <p className="font-medium text-sm">{achievement.title}</p>
                      <p className="text-xs text-gray-500 dark:text-gray-400">{achievement.desc}</p>
                    </div>
                  </div>
                ))}
              </div>
            </CardContent>
          </Card>
        </motion.div>
      </div>
    </div>
  );
};

export default AnalyticsDashboard;

