import React, { useEffect, useRef } from 'react';
import { useAuth } from '@/features/auth/useAuth';

/**
 * Componente de watermark dinámico para contenido sensible
 * Superpone información de identificación sobre media protegida
 */

interface DynamicWatermarkProps {
  children: React.ReactNode;
  intensity?: 'light' | 'medium' | 'heavy';
  showUserId?: boolean;
  showTimestamp?: boolean;
  customText?: string;
  className?: string;
}

export const DynamicWatermark: React.FC<DynamicWatermarkProps> = ({
  children,
  intensity = 'medium',
  showUserId = true,
  showTimestamp = true,
  customText,
  className = ''
}) => {
  const { user } = useAuth();
  const containerRef = useRef<HTMLDivElement>(null);

  const generateWatermarkText = (): string => {
    const parts: string[] = [];

    if (customText) {
      parts.push(customText);
    }

    if (showUserId && user?.id) {
      parts.push(`ID: ${user.id.slice(-8)}`);
    }

    if (showTimestamp) {
      const now = new Date();
      parts.push(now.toLocaleString('es-MX', { 
        timeZone: 'America/Mexico_City',
        hour12: false,
        year: '2-digit',
        month: '2-digit',
        day: '2-digit',
        hour: '2-digit',
        minute: '2-digit'
      }));
    }

    return parts.join(' • ');
  };

  const getIntensitySettings = () => {
    switch (intensity) {
      case 'light':
        return {
          opacity: 0.1,
          fontSize: '10px',
          spacing: '150px',
          angle: 15
        };
      case 'heavy':
        return {
          opacity: 0.3,
          fontSize: '14px',
          spacing: '80px',
          angle: 45
        };
      default: // medium
        return {
          opacity: 0.2,
          fontSize: '12px',
          spacing: '120px',
          angle: 30
        };
    }
  };

  useEffect(() => {
    if (!containerRef.current) return;

    const settings = getIntensitySettings();
    const watermarkText = generateWatermarkText();

    // Crear patrón de watermark repetido
    const createWatermarkPattern = () => {
      const canvas = document.createElement('canvas') as HTMLCanvasElement;
      const ctx = canvas.getContext('2d');
      if (!ctx) return '';

      canvas.width = 300;
      canvas.height = 150;

      ctx.font = `${settings.fontSize} Arial`;
      ctx.fillStyle = `rgba(255, 255, 255, ${settings.opacity})`;
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';

      // Rotar el texto
      ctx.translate(canvas.width / 2, canvas.height / 2);
      ctx.rotate((settings.angle * Math.PI) / 180);

      // Dibujar texto con sombra para mejor visibilidad
      ctx.shadowColor = 'rgba(0, 0, 0, 0.3)';
      ctx.shadowBlur = 2;
      ctx.shadowOffsetX = 1;
      ctx.shadowOffsetY = 1;

      ctx.fillText(watermarkText, 0, 0);

      return canvas.toDataURL();
    };

    const watermarkDataUrl = createWatermarkPattern();

    // Aplicar watermark como background
    const container = containerRef.current;
    const watermarkOverlay = document.createElement('div');

    watermarkOverlay.style.cssText = `
      position: absolute;
      top: 0;
      left: 0;
      width: 100%;
      height: 100%;
      pointer-events: none;
      z-index: 1000;
      background-image: url(${watermarkDataUrl});
      background-repeat: repeat;
      background-size: ${settings.spacing} auto;
      mix-blend-mode: overlay;
      user-select: none;
      -webkit-user-select: none;
    `;

    watermarkOverlay.setAttribute('data-watermark', 'true');
    container.appendChild(watermarkOverlay as Node);

    return () => {
      const existingWatermark = container.querySelector('[data-watermark="true"]');
      if (existingWatermark) {
        container.removeChild(existingWatermark);
      }
    };
  }, [user?.id, intensity, showUserId, showTimestamp, customText]);

  // Protección adicional contra manipulación del DOM
  useEffect(() => {
    if (!containerRef.current) return;

    const observer = new MutationObserver((mutations) => {
      mutations.forEach((mutation) => {
        if (mutation.type === 'childList') {
          mutation.removedNodes.forEach((node) => {
            if (node instanceof Element && node.getAttribute('data-watermark') === 'true') {
              // Re-crear watermark si es removido
              setTimeout(() => {
                if (containerRef.current) {
                  const event = new Event('watermark-refresh');
                  containerRef.current.dispatchEvent(event);
                }
              }, 100);
            }
          });
        }
      });
    });

    observer.observe(containerRef.current as Element, {
      childList: true,
      subtree: true
    });

    return () => observer.disconnect();
  }, []);

  return (
    <div 
      ref={containerRef}
      className={`relative overflow-hidden ${className}`}
      style={{ 
        position: 'relative',
        isolation: 'isolate' // Crear contexto de apilamiento
      }}
      onContextMenu={(e) => e.preventDefault()}
    >
      {children}

      {/* Watermark de esquina visible */}
      <div 
        className="absolute bottom-2 right-2 text-white text-xs bg-black bg-opacity-50 px-2 py-1 rounded pointer-events-none select-none"
        style={{ 
          fontSize: '10px',
          userSelect: 'none',
          WebkitUserSelect: 'none',
          zIndex: 1001
        }}
      >
        🛡️ Protegido
      </div>

      {/* Watermark invisible para detección */}
      <div 
        className="absolute inset-0 pointer-events-none select-none"
        style={{
          background: 'transparent',
          zIndex: 999,
          userSelect: 'none',
          WebkitUserSelect: 'none'
        }}
        data-security-layer="true"
        data-user-id={user?.id?.slice(-8)}
        data-timestamp={Date.now()}
      />
    </div>
  );
};

/**
 * Hook para aplicar watermark a elementos específicos
 */
export const useWatermark = (
  elementRef: React.RefObject<HTMLElement>,
  options: Omit<DynamicWatermarkProps, 'children'> = {}
) => {
  const { user } = useAuth();

  useEffect(() => {
    if (!elementRef.current || !user?.id) return;

    const element = elementRef.current;
    const settings = options.intensity === 'light' ? 
      { opacity: 0.1, fontSize: '10px' } :
      options.intensity === 'heavy' ?
      { opacity: 0.3, fontSize: '14px' } :
      { opacity: 0.2, fontSize: '12px' };

    // Aplicar watermark como pseudo-elemento
    const style = document.createElement('style');
    const watermarkId = `watermark-${Date.now()}`;

    style.textContent = `
      .${watermarkId}::before {
        content: "ID: ${user.id.slice(-8)} • ${new Date().toLocaleString('es-MX')}";
        position: absolute;
        top: 0;
        left: 0;
        width: 100%;
        height: 100%;
        opacity: ${settings.opacity};
        font-size: ${settings.fontSize};
        color: white;
        text-shadow: 1px 1px 2px rgba(0,0,0,0.5);
        pointer-events: none;
        user-select: none;
        z-index: 1000;
        display: flex;
        align-items: center;
        justify-content: center;
        transform: rotate(30deg);
        white-space: nowrap;
        overflow: hidden;
      }
    `;

    document.head.appendChild(style as Node);
    element.classList.add(watermarkId);

    return () => {
      element.classList.remove(watermarkId);
      if (style.parentNode) {
        style.parentNode.removeChild(style as Node);
      }
    };
  }, [elementRef, user?.id, options.intensity]);
};

export default DynamicWatermark;

import React, { useState, useEffect } from 'react';
import { Card } from '@/shared/ui/Card';
import { Button } from '@/shared/ui/Button';
import { Input } from '@/shared/ui/Input';
import { useToast } from '@/hooks/useToast';
import { 
  Heart, 
  MessageCircle, 
  Share2, 
  Eye, 
  X, 
  Send,
  Trash2,
  MapPin,
  Globe,
  Lock
} from 'lucide-react';
import { Story } from './StoryTypes';
import { storyService } from './StoryService';

interface StoryViewerProps {
  story: Story;
  onClose: () => void;
  onStoryChange?: (updatedStory: Story) => void;
}

export const StoryViewer: React.FC<StoryViewerProps> = ({ 
  story, 
  onClose, 
  onStoryChange 
}) => {
  const [currentStory, setCurrentStory] = useState<Story>(story);
  const [isLiked, setIsLiked] = useState(false);
  const [showComments, setShowComments] = useState(false);
  const [newComment, setNewComment] = useState('');
  const [isSubmittingComment, setIsSubmittingComment] = useState(false);
  const [progress, setProgress] = useState(0);
  const { toast } = useToast();

  const isDemoMode = localStorage.getItem('demo_authenticated') === 'true';
  const currentUserId = "1"; // Usuario demo

  useEffect(() => {
    // Marcar como vista
    storyService.markAsViewed(currentStory.id);
    
    // Verificar si ya le dio like
    const userLike = currentStory.likes?.find(like => like.userId === currentUserId);
    setIsLiked(!!userLike);

    // Simular progreso de la historia (15 segundos)
    const interval = setInterval(() => {
      setProgress(prev => {
        if (prev >= 100) {
          clearInterval(interval);
          onClose();
          return 100;
        }
        return prev + (100 / 150); // 15 segundos = 150 intervalos de 100ms
      });
    }, 100);

    return () => clearInterval(interval);
  }, [currentStory.id, currentUserId, onClose]);

  const formatTimeAgo = (dateString: string) => {
    const now = new Date();
    const storyDate = new Date(dateString);
    const diffInHours = Math.floor((now.getTime() - storyDate.getTime()) / (1000 * 60 * 60));
    
    if (diffInHours < 1) return 'Hace unos minutos';
    if (diffInHours < 24) return `Hace ${diffInHours}h`;
    return 'Expirada';
  };

  const handleLike = async () => {
    const success = await storyService.likeStory(currentStory.id);
    if (success) {
      setIsLiked(!isLiked);
      // Actualizar el estado local de la historia
      const updatedStory = { ...currentStory };
      if (isLiked) {
        // Quitar like
        updatedStory.likes = updatedStory.likes?.filter(like => like.userId !== currentUserId) || [];
      } else {
        // Agregar like
        const newLike = {
          id: `like_${Date.now()}`,
          storyId: currentStory.id.toString(),
          userId: currentUserId,
          createdAt: new Date(),
          user: { id: currentUserId, name: "Usuario Demo", avatar: "/src/assets/people/profile-1.jpg" }
        };
        updatedStory.likes = updatedStory.likes || [];
        updatedStory.likes.push(newLike);
      }
      setCurrentStory(updatedStory);
      onStoryChange?.(updatedStory);
    }
  };

  const handleComment = async () => {
    if (!newComment.trim() || isSubmittingComment) return;

    setIsSubmittingComment(true);
    const success = await storyService.commentStory(currentStory.id, newComment.trim());
    
    if (success) {
      const updatedStory = { ...currentStory };
      const newCommentObj = {
        id: `comment_${Date.now()}`,
        storyId: currentStory.id.toString(),
        userId: currentUserId,
        comment: newComment.trim(),
        createdAt: new Date(),
        user: { id: currentUserId, name: "Usuario Demo", avatar: "/src/assets/people/profile-1.jpg" }
      };
      
      updatedStory.comments = updatedStory.comments || [];
      updatedStory.comments.push(newCommentObj);
      setCurrentStory(updatedStory);
      onStoryChange?.(updatedStory);
      setNewComment('');
    }
    
    setIsSubmittingComment(false);
  };

  const handleShare = async () => {
    const shareUrl = await storyService.shareStory(currentStory.id);
    if (shareUrl) {
      if (navigator.share) {
        navigator.share({
          title: `Historia de ${currentStory.user.name}`,
          text: currentStory.description || 'Mira esta historia',
          url: shareUrl
        });
      } else {
        navigator.clipboard.writeText(shareUrl);
        toast({
          title: "¡Enlace copiado!",
          description: "El enlace de la historia se ha copiado al portapapeles",
          duration: 3000,
        });
      }
    }
  };

  const handleDeleteComment = async (commentId: string) => {
    const success = await storyService.deleteComment(currentStory.id, commentId);
    if (success) {
      const updatedStory = { ...currentStory };
      updatedStory.comments = updatedStory.comments?.filter(c => c.id !== commentId) || [];
      setCurrentStory(updatedStory);
      onStoryChange?.(updatedStory);
    }
  };

  const isOwner = currentStory.userId.toString() === currentUserId;

  return (
    <div className="fixed inset-0 bg-black/95 backdrop-blur-sm flex items-center justify-center z-50">
      <div className="relative w-full max-w-md h-full max-h-[90vh] mx-4">
        {/* Barra de progreso */}
        <div className="absolute top-4 left-4 right-4 z-10">
          <div className="w-full h-1 bg-white/30 rounded-full">
            <div 
              className="h-full bg-white rounded-full transition-all duration-100 ease-linear" 
              style={{ width: `${progress}%` }}
            />
          </div>
        </div>
        
        {/* Header */}
        <div className="absolute top-8 left-4 right-4 z-10 flex items-center justify-between">
          <div className="flex items-center space-x-2">
            <img 
              src={currentStory.user.avatar} 
              alt={currentStory.user.name}
              className="w-8 h-8 rounded-full border-2 border-white"
            />
            <div>
              <p className="text-white font-medium text-sm">{currentStory.user.name}</p>
              <div className="flex items-center gap-2">
                <p className="text-white/70 text-xs">{formatTimeAgo(currentStory.createdAt)}</p>
                {currentStory.location && (
                  <div className="flex items-center gap-1">
                    <MapPin className="h-3 w-3 text-white/70" />
                    <p className="text-white/70 text-xs">{currentStory.location}</p>
                  </div>
                )}
                <div className="flex items-center gap-1">
                  {currentStory.visibility === 'private' ? (
                    <Lock className="h-3 w-3 text-white/70" />
                  ) : (
                    <Globe className="h-3 w-3 text-white/70" />
                  )}
                </div>
              </div>
            </div>
          </div>
          
          <Button
            onClick={onClose}
            variant="ghost"
            size="sm"
            className="text-white hover:bg-white/10"
          >
            <X className="h-4 w-4" />
          </Button>
        </div>
        
        {/* Contenido */}
        <Card className="h-full bg-black border-white/20 overflow-hidden">
          {currentStory.content.type === 'image' ? (
            <div className="relative h-full">
              <img 
                src={currentStory.content.url || 'data:image/svg+xml;base64,'} 
                alt="Historia"
                className="w-full h-full object-cover"
                onError={(e) => {
                  const target = e.target as HTMLImageElement;
                  target.src = 'data:image/svg+xml;base64,';
                  target.onerror = null; // Prevenir loops infinitos
                }}
              />
              {currentStory.description && (
                <div className="absolute bottom-20 left-4 right-4">
                  <div className="bg-black/50 backdrop-blur-sm rounded-lg p-3">
                    <p className="text-white text-sm drop-shadow-lg">{currentStory.description}</p>
                  </div>
                </div>
              )}
            </div>
          ) : currentStory.content.type === 'video' ? (
            <video 
              src={currentStory.content.url} 
              className="w-full h-full object-cover"
              autoPlay
              muted
              loop
            />
          ) : (
            <div className="h-full flex items-center justify-center bg-gradient-to-br from-purple-600 to-pink-600">
              <div className="text-center px-8">
                <p className="text-white text-xl font-bold mb-4">
                  {currentStory.content.text}
                </p>
                {currentStory.description && (
                  <p className="text-white/80 text-sm">{currentStory.description}</p>
                )}
              </div>
            </div>
          )}
        </Card>
        
        {/* Controles inferiores */}
        <div className="absolute bottom-4 left-4 right-4 z-10 space-y-3">
          {/* Stats */}
          <div className="flex items-center justify-between text-white text-sm">
            <div className="flex items-center space-x-4">
              <div className="flex items-center space-x-1">
                <Eye className="h-4 w-4" />
                <span>{currentStory.views}</span>
              </div>
              <div className="flex items-center space-x-1">
                <Heart className="h-4 w-4" />
                <span>{currentStory.likes?.length || 0}</span>
              </div>
              <div className="flex items-center space-x-1">
                <MessageCircle className="h-4 w-4" />
                <span>{currentStory.comments?.length || 0}</span>
              </div>
            </div>
          </div>

          {/* Action Buttons */}
          <div className="flex items-center justify-between">
            <div className="flex items-center space-x-2">
              <Button
                onClick={handleLike}
                size="sm"
                variant="ghost"
                className={`text-white hover:bg-white/10 ${isLiked ? 'text-red-400' : ''}`}
              >
                <Heart className={`h-4 w-4 ${isLiked ? 'fill-current' : ''}`} />
              </Button>
              <Button
                onClick={() => setShowComments(!showComments)}
                size="sm"
                variant="ghost"
                className="text-white hover:bg-white/10"
              >
                <MessageCircle className="h-4 w-4" />
              </Button>
              <Button
                onClick={handleShare}
                size="sm"
                variant="ghost"
                className="text-white hover:bg-white/10"
              >
                <Share2 className="h-4 w-4" />
              </Button>
            </div>
          </div>

          {/* Comments Section */}
          {showComments && (
            <div className="bg-black/50 backdrop-blur-sm rounded-lg p-3 max-h-40 overflow-y-auto">
              <div className="space-y-2 mb-3">
                {currentStory.comments && currentStory.comments.length > 0 ? (
                  currentStory.comments
                    .filter(comment => comment.comment && comment.comment.trim().length > 0) // Filtrar comentarios vacíos
                    .map((comment) => (
                      <div key={comment.id} className="flex items-start gap-2">
                        <img 
                          src={comment.user.avatar || 'data:image/svg+xml;base64,'} 
                          alt={comment.user.name}
                          className="w-6 h-6 rounded-full border border-white/20 flex-shrink-0"
                          onError={(e) => {
                            const target = e.target as HTMLImageElement;
                            target.src = 'data:image/svg+xml;base64,';
                            target.onerror = null;
                          }}
                        />
                        <div className="flex-1 min-w-0">
                          <div className="flex items-center gap-2">
                            <p className="text-white text-xs font-medium drop-shadow-md">{comment.user.name}</p>
                            {(isOwner || comment.userId === currentUserId) && (
                              <Button
                                onClick={() => handleDeleteComment(comment.id)}
                                size="sm"
                                variant="ghost"
                                className="h-4 w-4 p-0 text-red-400 hover:bg-red-400/10"
                              >
                                <Trash2 className="h-3 w-3" />
                              </Button>
                            )}
                          </div>
                          <p className="text-white/90 text-xs drop-shadow-md">{comment.comment}</p>
                        </div>
                      </div>
                    ))
                ) : (
                  <p className="text-white/60 text-xs text-center py-2">No hay comentarios aún</p>
                )}
              </div>
              
              <div className="flex gap-2">
                <Input
                  value={newComment}
                  onChange={(e) => setNewComment(e.target.value)}
                  placeholder="Escribe un comentario..."
                  className="bg-white/10 border-white/20 text-white placeholder:text-white/50 text-sm"
                  onKeyPress={(e) => e.key === 'Enter' && handleComment()}
                />
                <Button
                  onClick={handleComment}
                  disabled={!newComment.trim() || isSubmittingComment}
                  size="sm"
                  className="bg-gradient-to-r from-purple-500 to-blue-500 hover:from-purple-600 hover:to-blue-600 text-white font-semibold shadow-lg drop-shadow-md disabled:opacity-50 disabled:cursor-not-allowed"
                >
                  <Send className="h-4 w-4 mr-1" />
                  <span className="drop-shadow-md">Enviar</span>
                </Button>
              </div>
            </div>
          )}

          {/* Demo Notice */}
          {isDemoMode && (
            <div className="bg-yellow-500/20 border border-yellow-500/30 rounded-lg p-2">
              <p className="text-yellow-200 text-xs text-center">
                📱 Modo Demo: Las interacciones son simuladas
              </p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

import { useState, useEffect } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '@/shared/ui/Card';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/shared/ui/Button';
import { Input } from '@/shared/ui/Input';
import { Coins, Gift, Users, TrendingUp, Copy, Check, Sparkles, Image as ImageIcon } from 'lucide-react';
// import { getUserTokenBalance, processReferralReward, validateReferralCode, TOKEN_CONFIG } from '@/lib/tokens'; // Eliminado
// Mock functions para compatibilidad
const TOKEN_CONFIG = {
  REFERRAL_REWARD: 50,
  WELCOME_BONUS: 50,
  MONTHLY_LIMIT: 500,
  RESET_DAY: 1,
};

const getUserTokenBalance = (userId: string) => ({
  userId,
  cmpxBalance: 0,
  monthlyEarned: 0,
  lastResetDate: new Date().toISOString(),
  referralCode: `CMPX${userId.slice(-6).toUpperCase()}`,
  totalReferrals: 0
});

const processReferralReward = async (code: string, userId: string) => ({
  success: false,
  message: 'Función migrada a TokenService'
});

const validateReferralCode = (code: string) => /^CMPX[A-Z0-9]{6}$/.test(code);
import { useToast } from '@/hooks/useToast';
import { useNavigate } from 'react-router-dom';

interface TokenBalanceProps {
  userId: string;
}

export function TokenBalance({ userId }: TokenBalanceProps) {
  const [balance, setBalance] = useState(getUserTokenBalance(userId));
  const [referralCode, setReferralCode] = useState('');
  const [isProcessing, setIsProcessing] = useState(false);
  const [copied, setCopied] = useState(false);
  const { toast } = useToast();
  const navigate = useNavigate();

  useEffect(() => {
    setBalance(getUserTokenBalance(userId));
  }, [userId]);

  const handleReferralSubmit = async () => {
    if (!referralCode.trim()) {
      toast({
        title: "Error",
        description: "Ingresa un código de referido",
        variant: "destructive"
      });
      return;
    }

    if (!validateReferralCode(referralCode)) {
      toast({
        title: "Código inválido",
        description: "El formato debe ser CMPX seguido de 6 caracteres",
        variant: "destructive"
      });
      return;
    }

    setIsProcessing(true);
    
    try {
      const result = await processReferralReward(referralCode, userId);
      
      if (result.success) {
        setBalance(getUserTokenBalance(userId));
        setReferralCode('');
        toast({
          title: "¡Recompensa recibida!",
          description: result.message,
          variant: "default"
        });
      } else {
        toast({
          title: "Error",
          description: result.message,
          variant: "destructive"
        });
      }
    } catch {
      toast({
        title: "Error",
        description: "Error al procesar el código de referido",
        variant: "destructive"
      });
    } finally {
      setIsProcessing(false);
    }
  };

  const copyReferralCode = async () => {
    try {
      await navigator.clipboard.writeText(balance.referralCode);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
      toast({
        title: "¡Copiado!",
        description: "Código de referido copiado al portapapeles",
        variant: "default"
      });
    } catch {
      toast({
        title: "Error",
        description: "No se pudo copiar el código",
        variant: "destructive"
      });
    }
  };

  const remainingLimit = TOKEN_CONFIG.MONTHLY_LIMIT - balance.monthlyEarned;
  const progressPercentage = (balance.monthlyEarned / TOKEN_CONFIG.MONTHLY_LIMIT) * 100;

  return (
    <div className="space-y-6">
      {/* Balance Principal */}
      <Card className="bg-gradient-to-r from-purple-900/80 to-pink-900/80 backdrop-blur-sm border border-white/10">
        <CardHeader>
          <CardTitle className="flex items-center gap-2 text-white">
            <Coins className="h-6 w-6 text-yellow-400" />
            Balance CMPX
          </CardTitle>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="text-center">
            <div className="text-4xl font-bold text-white mb-2">
              {balance.cmpxBalance.toLocaleString('es-MX')}
            </div>
            <div className="text-white/70">CMPX Disponibles</div>
          </div>
          
          <div className="grid grid-cols-2 gap-4">
            <div className="text-center p-3 bg-white/10 rounded-lg">
              <div className="text-lg font-semibold text-white">
                {balance.monthlyEarned}
              </div>
              <div className="text-xs text-white/70">Ganados este mes</div>
            </div>
            <div className="text-center p-3 bg-white/10 rounded-lg">
              <div className="text-lg font-semibold text-white">
                {remainingLimit}
              </div>
              <div className="text-xs text-white/70">Restantes este mes</div>
            </div>
          </div>

          {/* Barra de progreso mensual */}
          <div className="space-y-2">
            <div className="flex justify-between text-sm text-white/70">
              <span>Límite mensual</span>
              <span>{balance.monthlyEarned}/{TOKEN_CONFIG.MONTHLY_LIMIT}</span>
            </div>
            <div className="w-full bg-white/20 rounded-full h-2">
              <div 
                className="bg-gradient-to-r from-yellow-400 to-orange-500 h-2 rounded-full transition-all duration-300 progress-bar"
                data-progress={Math.min(progressPercentage, 100)}
              />
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Tu Código de Referido */}
      <Card className="bg-card/80 backdrop-blur-sm border border-primary/10">
        <CardHeader>
          <CardTitle className="flex items-center gap-2 text-white">
            <Gift className="h-5 w-5 text-green-400" />
            Tu Código de Referido
          </CardTitle>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="flex items-center gap-2 p-3 bg-gradient-to-r from-green-900/30 to-blue-900/30 rounded-lg">
            <code className="flex-1 text-lg font-mono text-white bg-black/30 px-3 py-2 rounded">
              {balance.referralCode}
            </code>
            <Button
              variant="ghost"
              size="sm"
              onClick={copyReferralCode}
              className="text-white hover:bg-white/10"
            >
              {copied ? <Check className="h-4 w-4" /> : <Copy className="h-4 w-4" />}
            </Button>
          </div>
          
          <div className="text-sm text-white/70">
            Comparte este código y gana <strong className="text-yellow-400">{TOKEN_CONFIG.REFERRAL_REWARD} CMPX</strong> por cada amigo que se registre.
          </div>
          
          <div className="flex items-center gap-2 text-sm text-white/60">
            <Users className="h-4 w-4" />
            <span>{balance.totalReferrals} referidos exitosos</span>
          </div>
        </CardContent>
      </Card>

      {/* Canjear Código de Referido */}
      <Card className="bg-card/80 backdrop-blur-sm border border-primary/10">
        <CardHeader>
          <CardTitle className="flex items-center gap-2 text-white">
            <TrendingUp className="h-5 w-5 text-blue-400" />
            Canjear Código de Referido
          </CardTitle>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="space-y-2">
            <Input
              placeholder="Ingresa código (ej: CMPXABC123)"
              value={referralCode}
              onChange={(e) => setReferralCode(e.target.value.toUpperCase())}
              className="bg-white/10 border-white/20 text-white placeholder:text-white/50"
              maxLength={10}
            />
          </div>
          
          <Button
            onClick={handleReferralSubmit}
            disabled={isProcessing || !referralCode.trim()}
            className="w-full bg-gradient-to-r from-green-600 to-blue-600 hover:from-green-700 hover:to-blue-700"
          >
            {isProcessing ? 'Procesando...' : `Canjear (+${TOKEN_CONFIG.WELCOME_BONUS} CMPX)`}
          </Button>
          
          <div className="text-xs text-white/60 text-center">
            Recibirás <strong className="text-green-400">{TOKEN_CONFIG.WELCOME_BONUS} CMPX</strong> de bienvenida al usar un código válido
          </div>
        </CardContent>
      </Card>

      {/* Galerías NFT */}
      <Card className="bg-gradient-to-r from-purple-900/80 to-indigo-900/80 backdrop-blur-sm border border-white/10">
        <CardHeader>
          <CardTitle className="flex items-center gap-2 text-white">
            <Sparkles className="h-5 w-5 text-purple-400" />
            Galerías NFT-Verificadas
          </CardTitle>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="text-sm text-white/80">
            Convierte tus galerías en NFTs verificados usando tokens <strong className="text-purple-300">GTK</strong>. 
            Verifica la autenticidad de tus fotos en blockchain.
          </div>
          
          <div className="grid grid-cols-2 gap-3 text-sm">
            <div className="p-3 bg-white/10 rounded-lg">
              <div className="text-white/70 mb-1">Costo Galería</div>
              <div className="text-lg font-semibold text-white">1,000 GTK</div>
            </div>
            <div className="p-3 bg-white/10 rounded-lg">
              <div className="text-white/70 mb-1">Costo Imagen</div>
              <div className="text-lg font-semibold text-white">100 GTK</div>
            </div>
          </div>

          <Button
            onClick={() => navigate('/profile?tab=nft-galleries')}
            className="w-full bg-gradient-to-r from-purple-600 to-indigo-600 hover:from-purple-700 hover:to-indigo-700 text-white"
          >
            <ImageIcon className="h-4 w-4 mr-2" />
            Gestionar Galerías NFT
          </Button>

          <div className="text-xs text-white/60 text-center">
            💡 Los NFTs se activarán en blockchain en Q2 2026. Actualmente en preparación.
          </div>
        </CardContent>
      </Card>

      {/* Información del Sistema */}
      <Card className="bg-card/80 backdrop-blur-sm border border-primary/10">
        <CardContent className="pt-6">
          <div className="grid grid-cols-2 gap-4 text-center">
            <div>
              <Badge variant="secondary" className="mb-2">
                Por Referido
              </Badge>
              <div className="text-lg font-semibold text-white">
                {TOKEN_CONFIG.REFERRAL_REWARD} CMPX
              </div>
            </div>
            <div>
              <Badge variant="secondary" className="mb-2">
                Límite Mensual
              </Badge>
              <div className="text-lg font-semibold text-white">
                {TOKEN_CONFIG.MONTHLY_LIMIT} CMPX
              </div>
            </div>
          </div>
          
          <div className="mt-4 text-xs text-white/60 text-center">
            Los CMPX son tokens internos de ComplicesConecta. En futuras versiones podrán convertirse en GTK (blockchain).
            Los GTK se usan para mint NFTs y hacer staking.
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

