            <p className="text-sm">{getHoverInfo(card.filterType)}</p>
          </TooltipContent>
        </Tooltip>
      </motion.div>
    </TooltipProvider>
  );
};

import * as React from "react";
import { motion, HTMLMotionProps } from "framer-motion";
import { cn } from "@/shared/lib/cn";

interface GlassCardProps extends HTMLMotionProps<"div"> {
  variant?: "default" | "frosted" | "minimal" | "colored";
  blur?: "sm" | "md" | "lg" | "xl";
  opacity?: number;
  gradient?: boolean;
  border?: boolean;
  shadow?: "none" | "sm" | "md" | "lg" | "xl";
  children: React.ReactNode;
}

const variantStyles = {
  default: "bg-white/10 border-white/20",
  frosted: "bg-white/20 border-white/30",
  minimal: "bg-white/5 border-white/10",
  colored: "bg-gradient-to-br from-purple-500/20 to-pink-500/20 border-white/20"
};

const blurStyles = {
  sm: "backdrop-blur-sm",
  md: "backdrop-blur-md",
  lg: "backdrop-blur-lg",
  xl: "backdrop-blur-xl"
};

const shadowStyles = {
  none: "",
  sm: "shadow-sm",
  md: "shadow-md",
  lg: "shadow-lg",
  xl: "shadow-xl"
};

export const GlassCard = React.forwardRef<HTMLDivElement, GlassCardProps>(
  ({ 
    className,
    variant = "default",
    blur = "md",
    opacity = 0.1,
    gradient = false,
    border = true,
    shadow = "lg",
    children,
    style,
    ...props 
  }, ref) => {
    const customOpacity = opacity !== 0.1 ? { backgroundColor: `rgba(255, 255, 255, ${opacity})` } : {};
    
    return (
      <motion.div
        ref={ref}
        className={cn(
          "relative overflow-hidden rounded-xl",
          blurStyles[blur],
          shadowStyles[shadow],
          border && "border",
          gradient ? "bg-gradient-to-br from-white/10 to-white/5" : variantStyles[variant],
          className
        )}
        style={{ ...customOpacity, ...style }}
        initial={{ opacity: 0, y: 20, scale: 0.95 }}
        animate={{ opacity: 1, y: 0, scale: 1 }}
        whileHover={typeof window !== 'undefined' && window.matchMedia('(hover: hover)').matches ? { y: -2, scale: 1.01, transition: { type: "spring", stiffness: 400, damping: 25 } } : {}}
        transition={{ 
          duration: typeof window !== 'undefined' && window.matchMedia('(prefers-reduced-motion: reduce)').matches ? 0 : 0.3, 
          ease: "easeOut" 
        }}
        {...props}
      >
        {/* Animated Border Gradient */}
        {border && (
          <motion.div
            className="absolute inset-0 rounded-xl pointer-events-none"
            style={{
              background: "linear-gradient(45deg, transparent, rgba(255,255,255,0.1), transparent)",
              padding: "1px"
            }}
            animate={{
              rotate: [0, 360]
            }}
            transition={{
              duration: 8,
              repeat: Infinity,
              ease: "linear"
            }}
          >
            <div className="w-full h-full rounded-xl bg-transparent" />
          </motion.div>
        )}

        {/* Shimmer Effect */}
        <motion.div
          className="absolute inset-0 bg-gradient-to-r from-transparent via-white/5 to-transparent rounded-xl pointer-events-none"
          initial={{ x: "-100%" }}
          animate={{ x: "100%" }}
          transition={{
            duration: 3,
            repeat: Infinity,
            ease: "easeInOut",
            delay: Math.random() * 2
          }}
        />

        {/* Content */}
        <div className="relative z-10 p-6">
          {children}
        </div>
      </motion.div>
    );
  }
);

GlassCard.displayName = "GlassCard";

export default GlassCard;

import React from 'react';
import { cn } from '@/shared/lib/cn';
import { useAdaptiveBackground } from './AdaptiveBackground';

/**
 * GlassContainer Component
 * 
 * Contenedor con Glassmorphism condicional basado en el Tier del dispositivo.
 * 
 * - LOW Tier: Fondos sólidos (sin glassmorphism)
 * - MID Tier: Glassmorphism moderado (bg-white/10 backdrop-blur-md)
 * - HIGH Tier: Glassmorphism premium (bg-white/15 backdrop-blur-xl)
 */

interface GlassContainerProps {
  children: React.ReactNode;
  className?: string;
  variant?: 'card' | 'modal' | 'panel';
  showBorder?: boolean;
}

export const GlassContainer: React.FC<GlassContainerProps> = ({
  children,
  className,
  variant = 'card',
  showBorder = true,
}) => {
  const { tier, isLow, isMid, isHigh } = useAdaptiveBackground();

  // Determinar clases basadas en Tier
  const glassClasses = React.useMemo(() => {
    if (isLow) {
      // LOW Tier: Fondos sólidos sin glassmorphism
      return cn(
        'bg-white dark:bg-gray-900',
        showBorder && 'border border-gray-200 dark:border-gray-800'
      );
    }

    if (isMid) {
      // MID Tier: Glassmorphism moderado
      return cn(
        'bg-white/10 dark:bg-black/20',
        'backdrop-blur-md',
        showBorder && 'border border-white/20 dark:border-white/10'
      );
    }

    // HIGH Tier: Glassmorphism premium
    return cn(
      'bg-white/15 dark:bg-black/30',
      'backdrop-blur-xl',
      showBorder && 'border border-white/30 dark:border-white/20'
    );
  }, [tier, isLow, isMid, isHigh, showBorder]);

  // Clases específicas por variante
  const variantClasses = {
    card: 'rounded-2xl shadow-2xl',
    modal: 'rounded-3xl shadow-2xl',
    panel: 'rounded-xl shadow-lg',
  };

  return (
    <div
      className={cn(
        glassClasses,
        variantClasses[variant],
        'transition-all duration-300',
        className
      )}
      data-tier={tier}
    >
      {children}
    </div>
  );
};

/**
 * GlassButton Component
 * 
 * Botón con Glassmorphism condicional
 */

interface GlassButtonProps
  extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  children: React.ReactNode;
  variant?: 'primary' | 'secondary' | 'ghost';
}

export const GlassButton: React.FC<GlassButtonProps> = ({
  children,
  className,
  variant = 'primary',
  ...props
}) => {
  const { tier, isLow } = useAdaptiveBackground();

  const buttonClasses = React.useMemo(() => {
    if (isLow) {
      // LOW Tier: Botones sólidos
      return {
        primary: 'bg-purple-600 hover:bg-purple-700 text-white',
        secondary: 'bg-gray-200 hover:bg-gray-300 text-gray-900',
        ghost: 'bg-transparent hover:bg-gray-100 text-gray-900',
      };
    }

    // MID/HIGH Tier: Botones con glassmorphism
    return {
      primary: 'bg-white/20 hover:bg-white/30 backdrop-blur-md border border-white/30 text-white',
      secondary: 'bg-white/10 hover:bg-white/20 backdrop-blur-md border border-white/20 text-white',
      ghost: 'bg-transparent hover:bg-white/10 backdrop-blur-sm border border-white/10 text-white',
    };
  }, [tier, isLow]);

  return (
    <button
      className={cn(
        'px-6 py-2 rounded-lg font-medium transition-all duration-200',
        'hover:scale-105 active:scale-95',
        buttonClasses[variant],
        className
      )}
      {...props}
    >
      {children}
    </button>
  );
};

/**
 * GlassText Component
 * 
 * Texto con contraste mejorado para fondos transparentes
 */

interface GlassTextProps {
  children: React.ReactNode;
  className?: string;
  variant?: 'heading' | 'body' | 'caption';
}

export const GlassText: React.FC<GlassTextProps> = ({
  children,
  className,
  variant = 'body',
}) => {
  const { isLow } = useAdaptiveBackground();

  const textClasses = {
    heading: 'text-3xl font-bold',
    body: 'text-base font-normal',
    caption: 'text-sm font-medium',
  };

  return (
    <div
      className={cn(
        textClasses[variant],
        isLow
          ? 'text-gray-900 dark:text-white'
          : 'text-white drop-shadow-lg',
        className
      )}
    >
      {children}
    </div>
  );
};

