import React, { useEffect, useMemo, useState } from 'react';
import Particles, { initParticlesEngine } from '@tsparticles/react';
import { loadSlim } from '@tsparticles/slim';
import type { Engine } from '@tsparticles/engine';
import { useLocation } from 'react-router-dom';
import { cn } from '@/shared/lib/cn';
import { useBgMode } from '@/hooks/useBgMode';
import { useTheme } from '@/hooks/useTheme';
import { useAuth } from '@/features/auth/useAuth';
import { useAnimation } from '@/components/animations/AnimationProvider';
import { useDeviceCapability } from '@/hooks/useDeviceCapability';
import { useBackgroundPreferences } from '@/hooks/useBackgroundPreferences';

const STATIC_BACKGROUNDS = [
  '/backgrounds/bg1.jpg',
  '/backgrounds/bg2.jpg',
  '/backgrounds/bg3.jpg',
  '/backgrounds/bg4.jpg',
  '/backgrounds/bg5.webp',
];

export const GlobalBackground: React.FC<{ children?: React.ReactNode; className?: string }> = ({ children, className }) => {
  const { prefs } = useTheme();
  const { profile } = useAuth();
  const { mode, backgroundMode, setMode } = useBgMode();
  const { config } = useAnimation();
  const { pathname } = useLocation();
  const { tier, isLowEnd, allowParticles, allowBlur: _allowBlur } = useDeviceCapability();

  // Derivar propiedades de compatibilidad desde el hook simplificado
  const isHighEnd = tier === 'high';
  const isMediumEnd = tier === 'mid';
  const isMediumHigh = tier === 'mid' || tier === 'high';
  const enableFullAnimations = allowParticles;
  const deviceType = typeof window !== 'undefined' && window.innerWidth >= 1024 ? 'desktop' : 'mobile';
  const { preferences: bgPrefs } = useBackgroundPreferences();

  const [engineReady, setEngineReady] = useState(false);
  const [bgIndex, setBgIndex] = useState(() => Math.floor(Math.random() * STATIC_BACKGROUNDS.length));
  const [resolvedBackgroundImage, setResolvedBackgroundImage] = useState<string>('/backgrounds/bg1.jpg');
  const [fixedBgIndexSet, setFixedBgIndexSet] = useState(false);

  // Escuchar cambios en preferencias de background
  useEffect(() => {
    const handlePreferencesChange = () => {
      // Forzar re-render cuando cambien las preferencias
      setBgIndex(prev => prev);
    };
    window.addEventListener('backgroundPreferencesChanged', handlePreferencesChange);
    return () => window.removeEventListener('backgroundPreferencesChanged', handlePreferencesChange);
  }, []);

  useEffect(() => {
    const initEngine = async () => {
      try {
        await initParticlesEngine(async (engine: Engine) => {
          await loadSlim(engine);
        });
        setEngineReady(true);
      } catch (error) {
        console.error('Error initializing particles engine:', error);
        // Fallback: mostrar partículas de todas formas
        setEngineReady(true);
      }
    };
    initEngine();
  }, []);

  useEffect(() => {
    if (isLowEnd) return;
    if (!allowParticles) return;
    if (!bgPrefs.particlesEnabled) return;
    if (mode !== 'static') return;
    setMode('particles');
  }, [allowParticles, bgPrefs.particlesEnabled, isLowEnd, mode, setMode]);

  // Cambiar fondo según preferencias del usuario (useBgMode)
  useEffect(() => {
    // Usar backgroundMode de useBgMode (default: 'fixed')
    const effectiveMode = backgroundMode === 'random' ? 'random' : 'fixed';

    if (effectiveMode === 'random') {
      // Modo aleatorio: cambiar cada 5 segundos
      const interval = setInterval(() => {
        setBgIndex(Math.floor(Math.random() * STATIC_BACKGROUNDS.length));
      }, 5000);
      return () => clearInterval(interval);
    } else {
      // Modo fijo: usar imagen fija (no cambiar)
      // El bgIndex ya se estableció en el estado inicial
      if (!fixedBgIndexSet) {
        setFixedBgIndexSet(true);
      }
    }
  }, [backgroundMode, fixedBgIndexSet]);

  const backgroundImage = useMemo(() => {
    if (prefs?.isCustom && prefs.background) {
      return prefs.background;
    }
    return STATIC_BACKGROUNDS[bgIndex];
  }, [bgIndex, prefs?.background, prefs?.isCustom]);

  useEffect(() => {
    if (!backgroundImage) {
      setResolvedBackgroundImage(STATIC_BACKGROUNDS[0] || '/backgrounds/bg1.jpg');
      return;
    }

    let cancelled = false;
    const img = new Image();

    img.onload = () => {
      if (cancelled) return;
      setResolvedBackgroundImage(backgroundImage);
    };

    img.onerror = () => {
      // Fallback a la primera imagen si falla
      if (cancelled) return;
      setResolvedBackgroundImage(STATIC_BACKGROUNDS[0] || '/backgrounds/bg1.jpg');
    };

    img.src = backgroundImage;

    return () => {
      cancelled = true;
    };
  }, [backgroundImage]);

  const particlesOptions = useMemo(
    () => ({
      fullScreen: { enable: false },
      background: { color: { value: 'transparent' } },
      fpsLimit: isHighEnd ? 120 : (isMediumEnd ? 60 : 30),
      interactivity: {
        events: {
          onClick: { enable: true, mode: 'push' },
          onHover: { enable: true, mode: 'grab' },
        },
        modes: {
          push: { quantity: 4 },
          grab: { distance: 140, links: { opacity: 0.4 } },
        },
      },
      particles: {
        color: { value: '#a855f7' },
        links: {
          color: '#d8b4fe',
          distance: 150,
          enable: true,
          opacity: 0.25,
          width: 1,
        },
        move: {
          direction: 'none' as const,
          enable: true,
          outModes: { default: 'bounce' as const },
          random: false,
          speed: config.reducedMotion ? 0.4 : 1.4,
          straight: false,
        },
        number: {
          density: { enable: true, area: 800 },
          value: profile?.is_premium ? 120 : 70,
        },
        opacity: { value: 0.45 },
        shape: { type: 'circle' },
        size: { value: { min: 1, max: 3 } },
      },
      detectRetina: true,
    }),
    [config.reducedMotion, profile?.is_premium]
  );

  // Adaptar modo según capacidad del dispositivo
  let adaptiveMode = mode;

  if (isLowEnd) {
    // Gama baja: Solo gradientes sin animaciones
    adaptiveMode = 'static';
  } else if (isMediumEnd) {
    // Gama media: Desktop puede manejar partículas, mobile se queda en static
    adaptiveMode = deviceType === 'desktop' && enableFullAnimations ? 'particles' : 'static';
  } else if (isMediumHigh) {
    // Gama media-alta: Fondos aleatorios con opción de animaciones
    if (enableFullAnimations) {
      adaptiveMode = 'particles';
    } else {
      adaptiveMode = 'static';
    }
  } else if (isHighEnd) {
    // Gama alta: DESKTOP - Todo habilitado - partículas + backgrounds aleatorios
    // MOBILE/TABLET - Partículas con 120Hz
    if (deviceType === 'desktop') {
      // Desktop: Forzar partículas + backgrounds aleatorios
      adaptiveMode = 'particles';
    } else {
      // Mobile/Tablet: Usar modo configurado
      adaptiveMode = mode;
    }
  }

  const finalMode = adaptiveMode;
  // Respetar preferencia del usuario para partículas
  const showVideo =
    finalMode === 'video' &&
    enableFullAnimations &&
    !isLowEnd &&
    deviceType === 'desktop' &&
    bgPrefs.particlesEnabled &&
    config.enableBackgroundAnimations &&
    config.enableParticles &&
    !config.reducedMotion;
  const showParticles =
    (finalMode === 'particles' || (finalMode === 'static' && bgPrefs.particlesEnabled)) &&
    enableFullAnimations &&
    bgPrefs.particlesEnabled &&
    config.enableParticles &&
    !config.reducedMotion;

  const videoSrc = profile?.profile_type === 'couple'
    ? '/backgrounds/Animate-bg2.mp4'
    : '/backgrounds/animate-bg.mp4';

  return (
    <div className={cn('fixed inset-0 w-full h-full', className)} style={{ backgroundColor: '#1a0033' }}>
      {/* Fixed Background Layer */}
      <div className="absolute inset-0 z-0 w-full h-full overflow-hidden">
        {/* Imagen de Fondo (capa más baja) */}
        <div
          className="absolute inset-0 z-0 bg-cover bg-center bg-no-repeat pointer-events-none bg-gradient-to-br from-pink-900 via-purple-900 to-blue-900"
          style={{ 
            backgroundImage: `url(${resolvedBackgroundImage})`
          }}
        />

        {showVideo && (
          <video
            autoPlay
            loop
            muted
            playsInline
            className="absolute inset-0 z-0 w-full h-full object-cover opacity-80 pointer-events-none"
          >
            <source src={videoSrc} type="video/mp4" />
          </video>
        )}

        {/* Overlay Gradiente (encima de imagen, debajo de partículas) */}
        <div className="absolute inset-0 z-[1] pointer-events-none bg-gradient-to-t from-black/80 via-transparent to-black/20" />

        {/* Partículas (encima del gradiente) */}
        {engineReady && showParticles && (
          <div className="absolute inset-0 z-10 pointer-events-none">
            <Particles
              id="tsparticles-global"
              options={{
                ...particlesOptions,
                fullScreen: { enable: false },
                particles: {
                  ...particlesOptions.particles,
                  number: { value: profile?.is_premium ? 120 : 70 },
                },
              }}
              className="absolute inset-0 z-10 pointer-events-none"
            />
          </div>
        )}
      </div>

      {/* Scrollable Content Layer */}
      <div className="relative z-20 w-full h-full overflow-auto pointer-events-auto">
        {children}
      </div>
    </div>
  );
};

export default GlobalBackground;

import React, { useEffect, useState } from 'react';
import { useLocation } from 'react-router-dom';

interface PageBackgroundProps {
  children?: React.ReactNode;
  className?: string;
}

// Imágenes de fondo por ruta
const BACKGROUND_IMAGES = [
  '/backgrounds/bg1.jpg',
  '/backgrounds/bg2.jpg',
  '/backgrounds/bg3.jpg',
  '/backgrounds/bg4.jpg',
  '/backgrounds/bg5.webp',
];

const getBackgroundImageByPath = (pathname: string): string => {
  const pathHash = pathname.split('').reduce((acc, char) => acc + char.charCodeAt(0), 0);
  const index = pathHash % BACKGROUND_IMAGES.length;
  return BACKGROUND_IMAGES[index];
};

export const PageBackground: React.FC<PageBackgroundProps> = ({ children, className }) => {
  const location = useLocation();
  const [backgroundImage, setBackgroundImage] = useState(getBackgroundImageByPath(location.pathname));

  useEffect(() => {
    setBackgroundImage(getBackgroundImageByPath(location.pathname));
  }, [location.pathname]);

  return (
    <div className={`relative min-h-screen w-full overflow-hidden ${className || ''}`}>
      {/* Fondo imagen */}
      <div
        className="fixed inset-0 -z-20 bg-cover bg-center bg-no-repeat"
        style={{
          backgroundImage: `url(${backgroundImage})`,
        }}
      />

      {/* Overlay gradiente oscuro para mejor legibilidad */}
      <div className="fixed inset-0 -z-20 bg-gradient-to-br from-black/40 via-black/30 to-black/40" />

      {/* Partículas animadas - 55% opacidad (10% más visibles) */}
      <div className="fixed inset-0 -z-10 overflow-hidden">
        {Array.from({ length: 75 }).map((_, i) => (
          <div
            key={i}
            className="absolute rounded-full animate-float"
            style={{
              width: Math.random() * 4 + 2 + 'px',
              height: Math.random() * 4 + 2 + 'px',
              backgroundColor: '#a855f7',
              opacity: 0.55,
              left: Math.random() * 100 + '%',
              top: Math.random() * 100 + '%',
              animation: `float ${2 + Math.random() * 2}s ease-in-out infinite`,
              animationDelay: Math.random() * 2 + 's',
              filter: 'blur(0.5px)',
            }}
          />
        ))}
      </div>

      {/* Contenido */}
      <div className="relative z-0">
        {children}
      </div>
    </div>
  );
};

export const RandomBackground = PageBackground;
export const MasterBackground = PageBackground;

import { useState } from 'react';
import { Button } from '@/shared/ui/Button';
import { Sparkles, Loader2 } from 'lucide-react';
import { useChatSummary } from '@/features/chat/useChatSummary';
import { SummaryModal } from './SummaryModal';

interface SummaryButtonProps {
  chatId: string;
  className?: string;
}

/**
 * SummaryButton Component
 * 
 * Botón para generar resúmenes automáticos de conversaciones usando AI (GPT-4/BART)
 * 
 * Features:
 * - Genera resúmenes con un clic
 * - Muestra loading state durante generación
 * - Abre modal con el resumen generado
 * - Rate limiting: 10 resúmenes/día
 * - Cache de 24 horas
 * 
 * @example
 * ```tsx
 * <SummaryButton chatId="123" />
 * ```
 */
export function SummaryButton({ chatId, className }: SummaryButtonProps) {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const { summary, isLoading, error, usageStats, generateSummary, clearError } = useChatSummary();

  const handleClick = async () => {
    // Check rate limit
    if (usageStats && usageStats.usedToday >= usageStats.limit) {
      alert(`Has alcanzado el límite de ${usageStats.limit} resúmenes por día. Intenta mañana.`);
      return;
    }

    // Generate summary
    await generateSummary(chatId);

    // Open modal if successful
    if (summary) {
      setIsModalOpen(true);
    }
  };

  const handleModalClose = () => {
    setIsModalOpen(false);
    clearError();
  };

  return (
    <>
      <Button
        variant="outline"
        size="sm"
        onClick={handleClick}
        disabled={isLoading}
        className={className}
        title="Generar resumen de conversación con IA"
      >
        {isLoading ? (
          <>
            <Loader2 className="mr-2 h-4 w-4 animate-spin" />
            Generando...
          </>
        ) : (
          <>
            <Sparkles className="mr-2 h-4 w-4" />
            Resumen IA
          </>
        )}
      </Button>

      {summary && (
        <SummaryModal
          isOpen={isModalOpen}
          onClose={handleModalClose}
          summary={summary}
          error={error ? error.message : null}
        />
      )}

      {/* Error toast */}
      {error && !isModalOpen && (
        <div className="fixed bottom-4 right-4 bg-red-500 text-white px-4 py-2 rounded-lg shadow-lg">
          <p className="text-sm">{String(error)}</p>
          <button
            onClick={clearError}
            className="mt-2 text-xs underline hover:no-underline"
          >
            Cerrar
          </button>
        </div>
      )}
    </>
  );
}

import * as React from "react"
import { Slot } from "@radix-ui/react-slot"
import { type VariantProps, cva } from "class-variance-authority"
import { PanelLeft } from "lucide-react"

import { useIsMobile } from "@/hooks/use-mobile"
import { cn } from "@/shared/lib/cn"
import { Button } from "@/shared/ui/Button"
import { Input } from "@/shared/ui/Input"
import { Separator } from "@/components/ui/separator"
import { Sheet, SheetContent } from "@/components/ui/sheet"
import { Skeleton } from "@/components/ui/skeleton"
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from "@/components/ui/tooltip"

const SIDEBAR_COOKIE_NAME = "sidebar:state"
const SIDEBAR_COOKIE_MAX_AGE = 60 * 60 * 24 * 7
const _SIDEBAR_WIDTH = "16rem"
const SIDEBAR_WIDTH_MOBILE = "18rem"
const _SIDEBAR_WIDTH_ICON = "3rem"
const SIDEBAR_KEYBOARD_SHORTCUT = "b"

// CRÍTICO: Asegurar createContext disponible antes de usar
const safeCreateContext = <T,>(defaultValue: T | null): React.Context<T | null> => {
  const debugLog = (event: string, data?: any) => {
    if (typeof window !== 'undefined' && (window as any).__LOADING_DEBUG__) {
      (window as any).__LOADING_DEBUG__.log(event, data);
    }
  };
  
  if (typeof window !== 'undefined' && (window as any).React?.createContext) {
    debugLog('SAFE_CREATE_CONTEXT_GLOBAL', { provider: 'Sidebar', hasGlobal: true });
    return (window as any).React.createContext(defaultValue);
  }
  
  debugLog('SAFE_CREATE_CONTEXT_FALLBACK', { provider: 'Sidebar', hasGlobal: false, hasLocal: !!React.createContext });
  return React.createContext<T | null>(defaultValue);
};

type SidebarContext = {
  state: "expanded" | "collapsed"
  open: boolean
  setOpen: (open: boolean) => void
  openMobile: boolean
  setOpenMobile: (open: boolean) => void
  isMobile: boolean
  toggleSidebar: () => void
}

const SidebarContext = safeCreateContext<SidebarContext | null>(null)

function useSidebar() {
  const context = React.useContext(SidebarContext)
  if (!context) {
    throw new Error("useSidebar must be used within a SidebarProvider.")
  }

  return context
}

const SidebarProvider = React.forwardRef<
  HTMLDivElement,
  React.ComponentProps<"div"> & {
    defaultOpen?: boolean
    open?: boolean
    onOpenChange?: (open: boolean) => void
  }
>(
  (
    {
      defaultOpen = true,
      open: openProp,
      onOpenChange: setOpenProp,
      className,
      style: _style,
      children,
      ...props
    },
    ref
  ) => {
    const isMobile = useIsMobile()
    const [openMobile, setOpenMobile] = React.useState(false)

    // This is the internal state of the sidebar.
    // We use openProp and setOpenProp for control from outside the component.
    const [_open, _setOpen] = React.useState(defaultOpen)
    const open = openProp ?? _open
    const setOpen = React.useCallback(
      (value: boolean | ((value: boolean) => boolean)) => {
        const openState = typeof value === "function" ? value(open) : value
        if (setOpenProp) {
          setOpenProp(openState)
        } else {
          _setOpen(openState)
        }

        // This sets the cookie to keep the sidebar state.
        document.cookie = `${SIDEBAR_COOKIE_NAME}=${openState}; path=/; max-age=${SIDEBAR_COOKIE_MAX_AGE}`
      },
      [setOpenProp, open]
    )

    // Helper to toggle the sidebar.
    const toggleSidebar = React.useCallback(() => {
      return isMobile
        ? setOpenMobile((open) => !open)
        : setOpen((open) => !open)
    }, [isMobile, setOpen, setOpenMobile])

    // Adds a keyboard shortcut to toggle the sidebar.
    React.useEffect(() => {
      const handleKeyDown = (event: KeyboardEvent) => {
        if (
          event.key === SIDEBAR_KEYBOARD_SHORTCUT &&
          (event.metaKey || event.ctrlKey)
        ) {
          event.preventDefault()
          toggleSidebar()
        }
      }

      window.addEventListener("keydown", handleKeyDown)
      return () => window.removeEventListener("keydown", handleKeyDown)
    }, [toggleSidebar])

    // We add a state so that we can do data-state="expanded" or "collapsed".
    // This makes it easier to style the sidebar with Tailwind classes.
    const state = open ? "expanded" : "collapsed"

    const contextValue = React.useMemo<SidebarContext>(
      () => ({
        state,
        open,
        setOpen,
        isMobile,
        openMobile,
        setOpenMobile,
        toggleSidebar,
      }),
      [state, open, setOpen, isMobile, openMobile, setOpenMobile, toggleSidebar]
    )

    return (
      <SidebarContext.Provider value={contextValue}>
        <TooltipProvider delayDuration={0}>
          <div
            className={cn(
              "sidebar-wrapper group/sidebar-wrapper flex min-h-svh w-full has-[[data-variant=inset]]:bg-sidebar",
              className
            )}
            ref={ref}
            {...props}
          >
            {children}
          </div>
        </TooltipProvider>
      </SidebarContext.Provider>
    )
  }
)
SidebarProvider.displayName = "SidebarProvider"

const Sidebar = React.forwardRef<
  HTMLDivElement,
  React.ComponentProps<"div"> & {
    side?: "left" | "right"
    variant?: "sidebar" | "floating" | "inset"
    collapsible?: "offcanvas" | "icon" | "none"
  }
>(
  (
    {
      side = "left",
      variant = "sidebar",
      collapsible = "offcanvas",
      className,
      children,
      ...props
    },
    ref
  ) => {
    const { isMobile, state, openMobile, setOpenMobile } = useSidebar()

    if (collapsible === "none") {
      return (
        <div
          className={cn(
            "flex h-full w-[--sidebar-width] flex-col bg-sidebar text-sidebar-foreground",
            className
          )}
          ref={ref}
          {...props}
        >
          {children}
        </div>
      )
    }

    if (isMobile) {
      return (
        <Sheet open={openMobile} onOpenChange={setOpenMobile} {...props}>
          <SheetContent
            data-sidebar="sidebar"
            data-mobile="true"
            className="w-[--sidebar-width] bg-sidebar p-0 text-sidebar-foreground [&>button]:hidden"
            style={
              {
                "--sidebar-width": SIDEBAR_WIDTH_MOBILE,
              } as React.CSSProperties
            }
            side={side}
          >
            <div className="flex h-full w-full flex-col">{children}</div>
          </SheetContent>
        </Sheet>
      )
    }

    return (
      <div
        ref={ref}
        className="group peer hidden md:block text-sidebar-foreground"
        data-state={state}
        data-collapsible={state === "collapsed" ? collapsible : ""}
        data-variant={variant}
        data-side={side}
      >
        {/* This is what handles the sidebar gap on desktop */}
        <div
          className={cn(
            "duration-200 relative h-svh w-[--sidebar-width] bg-transparent transition-[width] ease-linear",
            "group-data-[collapsible=offcanvas]:w-0",
            "group-data-[side=right]:rotate-180",
            variant === "floating" || variant === "inset"
              ? "group-data-[collapsible=icon]:w-[calc(var(--sidebar-width-icon)_+_theme(spacing.4))]"
              : "group-data-[collapsible=icon]:w-[--sidebar-width-icon]"
          )}
        />
        <div
          className={cn(
            "duration-200 fixed inset-y-0 z-10 hidden h-svh w-[--sidebar-width] transition-[left,right,width] ease-linear md:flex",
            side === "left"
              ? "left-0 group-data-[collapsible=offcanvas]:left-[calc(var(--sidebar-width)*-1)]"
              : "right-0 group-data-[collapsible=offcanvas]:right-[calc(var(--sidebar-width)*-1)]",
            // Adjust the padding for floating and inset variants.
            variant === "floating" || variant === "inset"
              ? "p-2 group-data-[collapsible=icon]:w-[calc(var(--sidebar-width-icon)_+_theme(spacing.4)_+2px)]"
              : "group-data-[collapsible=icon]:w-[--sidebar-width-icon] group-data-[side=left]:border-r group-data-[side=right]:border-l",
            className
          )}
          {...props}
        >
          <div
            data-sidebar="sidebar"
            className="flex h-full w-full flex-col bg-sidebar group-data-[variant=floating]:rounded-lg group-data-[variant=floating]:border group-data-[variant=floating]:border-sidebar-border group-data-[variant=floating]:shadow"
          >
            {children}
          </div>
        </div>
      </div>
    )
  }
)
Sidebar.displayName = "Sidebar"

const SidebarTrigger = React.forwardRef<
  React.ElementRef<typeof Button>,
  React.ComponentProps<typeof Button>
>(({ className, onClick, ...props }, ref) => {
  const { toggleSidebar } = useSidebar()

  return (
    <Button
      ref={ref}
      data-sidebar="trigger"
      variant="ghost"
      size="icon"
      className={cn("h-7 w-7", className)}
      onClick={(event) => {
