import { useState, useEffect, useCallback, useRef } from 'react';
import { 
  advancedAnalyticsService, 
  AdvancedAnalyticsConfig, 
  AnalyticsDashboard,
  PredictiveInsights,
  AnalyticsAlert
} from '@/services/AdvancedAnalyticsService';
import { logger } from '@/lib/logger';

export interface UseAdvancedAnalyticsOptions {
  enableRealTimeUpdates?: boolean;
  updateInterval?: number; // milliseconds
  enableUserTracking?: boolean;
  enablePredictiveInsights?: boolean;
  onAlert?: (alert: AnalyticsAlert) => void;
  onInsight?: (insight: PredictiveInsights) => void;
}

export interface AnalyticsState {
  dashboard: AnalyticsDashboard | null;
  isLoading: boolean;
  error: string | null;
  lastUpdated: number | null;
  config: AdvancedAnalyticsConfig | null;
}

export function useAdvancedAnalytics(
  options: UseAdvancedAnalyticsOptions = {}
): AnalyticsState & {
  trackUserBehavior: (action: string, page: string, metadata?: Record<string, any>) => Promise<void>;
  refreshDashboard: () => Promise<void>;
  resolveAlert: (alertId: string) => Promise<void>;
  updateConfig: (config: Partial<AdvancedAnalyticsConfig>) => void;
  cleanupData: () => Promise<void>;
} {
  const {
    enableRealTimeUpdates = true,
    updateInterval = 30000,
    enableUserTracking = true,
    onAlert,
    onInsight
  } = options;

  const [state, setState] = useState<AnalyticsState>({
    dashboard: null,
    isLoading: true,
    error: null,
    lastUpdated: null,
    config: null
  });

  const intervalRef = useRef<NodeJS.Timeout | null>(null);
  const sessionIdRef = useRef<string>(`session-${Date.now()}-${Math.random()}`);

  // Función para cargar dashboard
  const loadDashboard = useCallback(async (): Promise<void> => {
    try {
      setState(prev => ({ ...prev, isLoading: true, error: null }));
      
      const dashboard = await advancedAnalyticsService.getAnalyticsDashboard();
      
      setState(prev => ({
        ...prev,
        dashboard,
        isLoading: false,
        lastUpdated: Date.now()
      }));

      // Notificar sobre nuevas alertas
      if (onAlert && dashboard.alerts.length > 0) {
        const latestAlert = dashboard.alerts[dashboard.alerts.length - 1];
        onAlert(latestAlert);
      }

      // Notificar sobre nuevos insights
      if (onInsight && dashboard.predictiveInsights.length > 0) {
        const latestInsight = dashboard.predictiveInsights[dashboard.predictiveInsights.length - 1];
        onInsight(latestInsight);
      }

    } catch (error) {
      const errorMessage = error instanceof Error ? error.message : 'Error desconocido';
      logger.error('Error loading analytics dashboard:', { error: errorMessage });
      
      setState(prev => ({
        ...prev,
        isLoading: false,
        error: errorMessage
      }));
    }
  }, [onAlert, onInsight]);

  // Función para rastrear comportamiento de usuario
  const trackUserBehavior = useCallback(async (
    action: string,
    page: string,
    metadata?: Record<string, any>
  ): Promise<void> => {
    if (!enableUserTracking) return;

    try {
      // Obtener userId del contexto de autenticación
      // TODO: Integrar con sistema de autenticación
      const userId = 'current-user-id'; // Placeholder
      
      await advancedAnalyticsService.trackUserBehavior(
        userId,
        sessionIdRef.current,
        action,
        page,
        metadata
      );

      logger.debug('User behavior tracked:', { action, page, metadata });
    } catch (error) {
      logger.error('Error tracking user behavior:', { error: String(error) });
    }
  }, [enableUserTracking]);

  // Función para refrescar dashboard
  const refreshDashboard = useCallback(async (): Promise<void> => {
    await loadDashboard();
  }, [loadDashboard]);

  // Función para resolver alerta
  const resolveAlert = useCallback(async (alertId: string): Promise<void> => {
    try {
      await advancedAnalyticsService.resolveAlert(alertId);
      await loadDashboard(); // Recargar para reflejar cambios
    } catch (error) {
      logger.error('Error resolving alert:', { error: String(error) });
    }
  }, [loadDashboard]);

  // Función para actualizar configuración
  const updateConfig = useCallback((config: Partial<AdvancedAnalyticsConfig>): void => {
    try {
      advancedAnalyticsService.updateConfig(config);
      logger.info('Analytics config updated:', { config });
    } catch (error) {
      logger.error('Error updating analytics config:', { error: String(error) });
    }
  }, []);

  // Función para limpiar datos
  const cleanupData = useCallback(async (): Promise<void> => {
    try {
      await advancedAnalyticsService.cleanupOldData();
      await loadDashboard(); // Recargar después de limpiar
    } catch (error) {
      logger.error('Error cleaning up analytics data:', { error: String(error) });
    }
  }, [loadDashboard]);

  // Cargar dashboard inicial
  useEffect(() => {
    loadDashboard();
  }, [loadDashboard]);

  // Configurar actualizaciones en tiempo real
  useEffect(() => {
    if (!enableRealTimeUpdates) return;

    intervalRef.current = setInterval(() => {
      loadDashboard();
    }, updateInterval);

    return () => {
      if (intervalRef.current) {
        clearInterval(intervalRef.current);
      }
    };
  }, [enableRealTimeUpdates, updateInterval, loadDashboard]);

  // Limpiar al desmontar
  useEffect(() => {
    return () => {
      if (intervalRef.current) {
        clearInterval(intervalRef.current);
      }
    };
  }, []);

  return {
    ...state,
    trackUserBehavior,
    refreshDashboard,
    resolveAlert,
    updateConfig,
    cleanupData
  };
}

// Hook para métricas específicas
export function useAnalyticsMetrics() {
  const { dashboard, isLoading, error } = useAdvancedAnalytics();
  
  const realTimeMetrics = dashboard?.realTimeMetrics || null;
  const userBehaviorMetrics = dashboard?.userBehaviorMetrics || [];
  const predictiveInsights = dashboard?.predictiveInsights || [];
  const performanceMetrics = dashboard?.performanceMetrics || null;
  const alerts = dashboard?.alerts || [];
  const trends = dashboard?.trends || null;

  return {
    realTimeMetrics,
    userBehaviorMetrics,
    predictiveInsights,
    performanceMetrics,
    alerts,
    trends,
    isLoading,
    error
  };
}

// Hook para insights predictivos
export function usePredictiveInsights() {
  const { predictiveInsights, isLoading, error } = useAnalyticsMetrics();
  
  const retentionInsights = predictiveInsights.filter(
    insight => insight.predictionType === 'user_retention'
  );
  
  const conversionInsights = predictiveInsights.filter(
    insight => insight.predictionType === 'conversion'
  );
  
  const churnInsights = predictiveInsights.filter(
    insight => insight.predictionType === 'churn'
  );
  
  const engagementInsights = predictiveInsights.filter(
    insight => insight.predictionType === 'engagement'
  );

  return {
    allInsights: predictiveInsights,
    retentionInsights,
    conversionInsights,
    churnInsights,
    engagementInsights,
    isLoading,
    error
  };
}

// Hook para alertas
export function useAnalyticsAlerts() {
  const { alerts, isLoading, error } = useAnalyticsMetrics();
  
  const criticalAlerts = alerts.filter(alert => alert.severity === 'critical');
  const highAlerts = alerts.filter(alert => alert.severity === 'high');
  const mediumAlerts = alerts.filter(alert => alert.severity === 'medium');
  const lowAlerts = alerts.filter(alert => alert.severity === 'low');
  
  const unresolvedAlerts = alerts.filter(alert => !alert.resolved);
  const resolvedAlerts = alerts.filter(alert => alert.resolved);

  return {
    allAlerts: alerts,
    criticalAlerts,
    highAlerts,
    mediumAlerts,
    lowAlerts,
    unresolvedAlerts,
    resolvedAlerts,
    isLoading,
    error
  };
}

// Hook para métricas de rendimiento
export function usePerformanceMetrics() {
  const { performanceMetrics, isLoading, error } = useAnalyticsMetrics();
  
  const cachePerformance = performanceMetrics?.cachePerformance || null;
  const databasePerformance = performanceMetrics?.databasePerformance || null;
  const memoryUsage = performanceMetrics?.memoryUsage || null;

  return {
    performanceMetrics,
    cachePerformance,
    databasePerformance,
    memoryUsage,
    isLoading,
    error
  };
}

export default useAdvancedAnalytics;

import { useState, useEffect, useCallback, useRef } from 'react';
import { advancedCacheService, CacheConfig, CacheStats } from '@/services/AdvancedCacheService';
import { logger } from '@/lib/logger';

export interface UseAdvancedCacheOptions {
  key: string;
  ttl?: number;
  priority?: number;
  dependencies?: string[];
  tags?: string[];
  enablePredictiveCache?: boolean;
  enableAdaptiveTTL?: boolean;
  onCacheHit?: (data: any) => void;
  onCacheMiss?: () => void;
  onError?: (error: Error) => void;
}

export interface CacheState<T> {
  data: T | null;
  isLoading: boolean;
  error: string | null;
  isFromCache: boolean;
  cacheStats: CacheStats | null;
  lastUpdated: number | null;
}

export function useAdvancedCache<T>(
  fetcher: () => Promise<T>,
  options: UseAdvancedCacheOptions
): CacheState<T> & {
  refetch: () => Promise<void>;
  invalidate: () => Promise<void>;
  preload: () => Promise<void>;
  updateCache: (data: T) => Promise<void>;
} {
  const [state, setState] = useState<CacheState<T>>({
    data: null,
    isLoading: false,
    error: null,
    isFromCache: false,
    cacheStats: null,
    lastUpdated: null
  });

  const fetcherRef = useRef(fetcher);
  const optionsRef = useRef(options);

  // Actualizar referencias cuando cambien
  useEffect(() => {
    fetcherRef.current = fetcher;
    optionsRef.current = options;
  }, [fetcher, options]);

  // Función para obtener datos
  const fetchData = useCallback(async (forceRefresh = false): Promise<void> => {
    const { key, ttl, priority: _priority = 1, dependencies: _dependencies = [], tags: _tags = [] } = optionsRef.current;
    
    try {
      setState(prev => ({ ...prev, isLoading: true, error: null }));

      // Intentar obtener desde cache si no es refresh forzado
      if (!forceRefresh) {
        const cachedData = await advancedCacheService.get<T>(key);
        if (cachedData !== null) {
          setState(prev => ({
            ...prev,
            data: cachedData,
            isLoading: false,
            isFromCache: true,
            lastUpdated: Date.now(),
            cacheStats: advancedCacheService.getStats()
          }));
          
          optionsRef.current.onCacheHit?.(cachedData);
          return;
        }
      }

      // Cache miss - obtener datos frescos
      optionsRef.current.onCacheMiss?.();
      const freshData = await fetcherRef.current();
      
      // Guardar en cache
      await advancedCacheService.set(key, freshData, ttl);
      
      setState(prev => ({
        ...prev,
        data: freshData,
        isLoading: false,
        isFromCache: false,
        lastUpdated: Date.now(),
        cacheStats: advancedCacheService.getStats()
      }));

    } catch (error) {
      const errorMessage = error instanceof Error ? error.message : 'Error desconocido';
      logger.error('Error fetching data:', { key, error: errorMessage });
      
      setState(prev => ({
        ...prev,
        isLoading: false,
        error: errorMessage,
        cacheStats: advancedCacheService.getStats()
      }));
      
      optionsRef.current.onError?.(error instanceof Error ? error : new Error(errorMessage));
    }
  }, []);

  // Función para refrescar datos
  const refetch = useCallback(async (): Promise<void> => {
    await fetchData(true);
  }, [fetchData]);

  // Función para invalidar cache
  const invalidate = useCallback(async (): Promise<void> => {
    const { key } = optionsRef.current;
    await advancedCacheService.delete(key);
    
    setState(prev => ({
      ...prev,
      data: null,
      isFromCache: false,
      cacheStats: advancedCacheService.getStats()
    }));
  }, []);

  // Función para pre-cargar datos
  const preload = useCallback(async (): Promise<void> => {
    const { key } = optionsRef.current;
    
    try {
      const cachedData = await advancedCacheService.get<T>(key);
      if (cachedData === null) {
        await fetchData();
      }
    } catch (error) {
      logger.error('Error preloading data:', { key, error: String(error) });
    }
  }, [fetchData]);

  // Función para actualizar cache manualmente
  const updateCache = useCallback(async (data: T): Promise<void> => {
    const { key, ttl } = optionsRef.current;
    
    try {
      await advancedCacheService.set(key, data, ttl);
      
      setState(prev => ({
        ...prev,
        data,
        isFromCache: true,
        lastUpdated: Date.now(),
        cacheStats: advancedCacheService.getStats()
      }));
    } catch (error) {
      logger.error('Error updating cache:', { key, error: String(error) });
    }
  }, []);

  // Cargar datos iniciales
  useEffect(() => {
    fetchData();
  }, [fetchData]);

  // Configurar cache predictivo si está habilitado
  useEffect(() => {
    const { enablePredictiveCache, key } = optionsRef.current;
    
    if (enablePredictiveCache) {
      // Simular patrón de acceso para predicción
      const accessPattern = [key];
      advancedCacheService.predictAndWarm(accessPattern);
    }
  }, []);

  return {
    ...state,
    refetch,
    invalidate,
    preload,
    updateCache
  };
}

// Hook para estadísticas del cache
export function useCacheStats() {
  const [stats, setStats] = useState<CacheStats | null>(null);
  const [performanceAnalysis, setPerformanceAnalysis] = useState<any>(null);

  const refreshStats = useCallback(() => {
    const currentStats = advancedCacheService.getStats();
    const analysis = advancedCacheService.getPerformanceAnalysis();
    
    setStats(currentStats);
    setPerformanceAnalysis(analysis);
  }, []);

  useEffect(() => {
    refreshStats();
    
    // Actualizar estadísticas cada 30 segundos
    const interval = setInterval(refreshStats, 30000);
    
    return () => clearInterval(interval);
  }, [refreshStats]);

  const optimizeCache = useCallback(async () => {
    await advancedCacheService.optimize();
    refreshStats();
  }, [refreshStats]);

  const clearCache = useCallback(async () => {
    await advancedCacheService.clear();
    refreshStats();
  }, [refreshStats]);

  const cleanupCache = useCallback(async () => {
    await advancedCacheService.cleanup();
    refreshStats();
  }, [refreshStats]);

  return {
    stats,
    performanceAnalysis,
    refreshStats,
    optimizeCache,
    clearCache,
    cleanupCache
  };
}

// Hook para configuración del cache
export function useCacheConfig() {
  const [config, setConfig] = useState<CacheConfig | null>(null);

  const updateConfig = useCallback((newConfig: Partial<CacheConfig>) => {
    advancedCacheService.updateConfig(newConfig);
    // TODO: Obtener configuración actual del servicio
    setConfig({ ...config, ...newConfig } as CacheConfig);
  }, [config]);

  const resetConfig = useCallback(() => {
    // TODO: Restaurar configuración por defecto
    logger.info('Cache config reset');
  }, []);

  return {
    config,
    updateConfig,
    resetConfig
  };
}

export default useAdvancedCache;

